window.C5=window.C5||{};C5.bgs={"t":"বাংলাদেশ ও বিশ্বপরিচয়","ch":[{"no":1,"title":"জলবায়ু পরিবর্তন","q":{"mcq":[{"n":"১","q":"নিচের কোনটি জীবাশ্ম জ্বালানি?","a":"গ) প্রাকৃতিক গ্যাস","o":["তাপশক্তি","সৌরশক্তি","প্রাকৃতিক গ্যাস","বায়ুপ্রবাহ"]},{"n":"২","q":"জলবায়ু পরিবর্তনের কারণে তাপমাত্রার কী পরিবর্তন হচ্ছে?","a":"ক) দ্রুত বাড়ছে","o":["দ্রুত বাড়ছে","কমে যাচ্ছে","একই রকম রয়েছে","ধীরে ধীরে বাড়ছে"]},{"n":"৩","q":"কৃষিকাজে প্রয়োজনীয় সেচের পানি না পাওয়ার মূল কারণ কী?","a":"গ) ভূগর্ভস্থ পানির স্তর নিচে নেমে যাওয়া","o":["সমুদ্রপৃষ্ঠের উচ্চতা বেড়ে যাওয়া","পৃথিবীর তাপমাত্রা বৃদ্ধি পাওয়া","ভূগর্ভস্থ পানির স্তর নিচে নেমে যাওয়া","দুই মেরুর বরফ গলে যাওয়া"]}],"blank":[{"n":"১","q":"প্লাস্টিকের ব্যবহার ______ দূষিত করে।","a":"পরিবেশ"},{"n":"২","q":"জীবাশ্ম জ্বালানি অধিকমাত্রায় ব্যবহারে বায়ুতে ______ বেড়ে যায়।","a":"কার্বন-ডাউ অক্সাইড"},{"n":"৩","q":"জলবায়ু পরিবর্তন রোধে ______ প্রয়োজন।","a":"বনায়ন"},{"n":"৪","q":"কংক্রিট ব্লকের ব্যবহার পরিবেশের ______ কমায়।","a":"দূষণ"}],"truefalse":[{"n":"১","q":"জলবায়ু পরিবর্তন হলে দুর্যোগের আশংকা কমে যায়।","a":"মিথ্যা"},{"n":"২","q":"অধিক বন উজাড়ের কারণে পৃথিবীর তাপমাত্রা কমে যাচ্ছে।","a":"মিথ্যা"},{"n":"৩","q":"তাপমাত্রা বৃদ্ধির ফলে জলবায়ুর পরিবর্তন ঘটে।","a":"সত্য"},{"n":"৪","q":"ডিজেল এক ধরনের জীবাশ্ম জ্বালানি।","a":"মিথ্যা"}],"short":[{"n":"১","q":"আবহাওয়া ও জলবায়ুর মধ্যে দুটি পার্থক্য লেখ।","a":"আবহাওয়া ও জলবায়ুর মধ্যে দুটি পার্থক্য—\nআবহাওয়া | জলবায়ু\nআবহাওয়া হলো স্বল্প সময়ের (ঘন্টা/দিন) অবস্থা। | জলবায়ু হলো দীর্ঘ সময়ের (বহু বছর) গড় অবস্থা।\nআবহাওয়া দ্রুত বদলায়। | জলবায়ু ধীরে ধীরে পরিবর্তিত হয়।"},{"n":"২","q":"জলবায়ু পরিবর্তনে মানবসৃষ্ট তিনটি কারণ লেখ।","a":"জলবায়ু পরিবর্তনে মানবসৃষ্ট তিনটি কারণ—\n• জীবাশ্ম জ্বালানি (যেমন—কয়লা/তেল/গ্যাস) বেশি পোড়ানোর ফলে কার্বন ডাইঅক্সাইড বাড়ে।\n• বন উজাড়/গাছ কাটার ফলে কার্বন ডাইঅক্সাইড শোষণ কমে যায়।\n• কারখানা ও যানবাহনের ধোঁয়া/গ্যাস নির্গমনের ফলে বায়ুদূষণ ও গ্রিনহাউস গ্যাস বাড়ে।"},{"n":"৩","q":"সমুদ্রপৃষ্ঠের উচ্চতা বেড়ে যাওয়ার তিনটি প্রভাব লেখ।","a":"সমুদ্রপৃষ্ঠের উচ্চতা বেড়ে যাওয়ার তিনটি প্রভাব—\n• উপকূলীয় এলাকায় লবণাক্ত পানি ঢুকে জমি ও পানির ক্ষতি হয়।\n• অনেক জায়গা পানিতে ডুবে/ভাঙনে ঘরবাড়ি ও রাস্তাঘাট নষ্ট হয়।\n• মানুষকে বাসস্থান হারিয়ে স্থানান্তরিত হতে হয় এবং কৃষি ক্ষতিগ্রস্ত হয়।"}],"essay":[{"n":"১","q":"জলবায়ু পরিবর্তন রোধে তোমার করণীয় লেখ।","a":"জলবায়ু পরিবর্তন রোধে আমি দৈনন্দিন জীবনে এমন কিছু অভ্যাস গড়ে তুলব যাতে ধোঁয়া-দূষণ কমে এবং প্রাকৃতিক ভারসাম্য বজায় থাকে। আমি বেশি বেশি গাছ লাগাব ও গাছের যত্ন নেব, কারণ গাছ কার্বন ডাইঅক্সাইড শোষণ করে পরিবেশকে শীতল রাখে। অপ্রয়োজনে বিদ্যুৎ নষ্ট করব না-লাইট, ফ্যান, টিভি, চার্জার ব্যবহার শেষে বন্ধ রাখব এবং সম্ভব হলে এসি কম ব্যবহার করব, যাতে বিদ্যুৎ উৎপাদনে জ্বালানি পোড়ানো কম হয়। যাতায়াতে হাঁটা, সাইকেল ও গণপরিবহন ব্যবহারের চেষ্টা করব, এতে ব্যক্তিগত গাড়ির ধোঁয়া কমবে। প্লাস্টিক ও পলিথিন কম ব্যবহার করব; কাপড় বা কাগজের ব্যাগ ব্যবহার করব এবং পরিবেশবান্ধব জিনিস বেছে নেব। ময়লা-আবর্জনা যেখানে-সেখানে ফেলব না, আবর্জনা পোড়াব না, ডাস্টবিনে ফেলব এবং সম্ভব হলে বর্জ্য আলাদা করে রাখব। পাশাপাশি পরিবার ও বন্ধুদেরও সচেতন করব, কারণ সবাই মিলে কাজ করলে জলবায়ু পরিবর্তন রোধে বড় ফল পাওয়া যায়।"},{"n":"২","q":"পরিবেশ সংরক্ষণে আমরা কীভাবে ভূমিকা রাখতে পারি?","a":"পরিবেশ সংরক্ষণে আমরা ছোট ছোট কাজ নিয়মিত করলে বড় পরিবর্তন আনা সম্ভব। আমাদের বাসা, স্কুল, রাস্তা ও আশেপাশে ময়লা না ফেলে ডাস্টবিনে ফেলতে হবে এবং প্লাস্টিক, কাগজ, খাবারের উচ্ছিষ্ট আলাদা করে ফেলতে পারলে রিসাইকেল করা সহজ হয় ও পরিবেশ পরিষ্কার থাকে। পানি সংরক্ষণ করতে হবে-অকারণে কল খোলা রাখা যাবে না, পানির অপচয় বন্ধ করতে হবে এবং পুকুর-খাল-নদীতে ময়লা ফেলতে দেওয়া যাবে না। বিদ্যুৎ ও জ্বালানি সাশ্রয় করতে হবে-অপ্রয়োজনে বাতি-ফ্যান চালু রাখা বন্ধ করা, সাশ্রয়ী বাল্ব ব্যবহার করা এবং হাঁটা/সাইকেল/গণপরিবহন ব্যবহার করার অভ্যাস গড়া দরকার। বেশি বেশি গাছ লাগানো ও বন রক্ষা করা জরুরি, কারণ গাছ কমে গেলে অক্সিজেন কমে এবং বন্যা-খরা-ঝড়ের ক্ষতি বাড়ে। পলিথিনের বদলে কাপড়ের ব্যাগ, প্লাস্টিকের বদলে কাচ/স্টিলের বোতল ব্যবহার এবং ক্ষতিকর কেমিক্যাল কম ব্যবহার করলে পরিবেশের ক্ষতি কমে। পাখি-প্রাণীদের প্রতি দয়া দেখানো, গরমে পানি রাখার ব্যবস্থা করা এবং শব্দদূষণ কমানোও পরিবেশ রক্ষায় সাহায্য করে। পরিবেশ রক্ষার বিষয়ে সবাইকে সচেতন করা, স্কুল-এলাকায় পরিচ্ছন্নতা অভিযান করা এবং নিয়ম মেনে চলার অভ্যাস গড়ে তুললে পরিবেশ সুন্দর থাকবে ও ভবিষ্যৎ প্রজন্ম নিরাপদ থাকবে।"}]}},{"no":2,"title":"আমরা মানুষ","q":{"mcq":[{"n":"১","q":"'একই কাজ বারবার করার প্রবণতা' নিচের কোন ধরনের শিশুর বৈশিষ্ট্য?","a":"খ) অটিস্টিক","o":["শারীরিক সমস্যাগ্রস্ত","অটিস্টিক","বুদ্ধিগত সমস্যাগ্রস্ত","শ্রবণ সমস্যাগ্রস্ত"]},{"n":"২","q":"সমতাভিত্তিক শিখন পরিবেশে ছেলেমেয়ে উভয়ের মধ্যে কী তৈরি হয়?","a":"খ) নিরাপত্তাবোধ","o":["হতাশা","নিরাপত্তাবোধ","অসহযোগিতার মনোভাব","একাকিত্ব"]}],"truefalse":[{"n":"১","q":"শারীরিক সমস্যাগ্রস্ত শিশুরা ধীর গতিতে কথা বলে।","a":"সত্য"},{"n":"২","q":"বিদ্যালয়ে মিলেমিশে কাজ করলে সকলে আত্মবিশ্বাসী হয়ে ওঠে।","a":"সত্য"},{"n":"৩","q":"মিলেমিশে কাজ করলে কাজে বেশি ভুল হয়।","a":"মিথ্যা"},{"n":"৪","q":"সমতাভিত্তিক শিখন পরিবেশে সবাই একে অপরের সুবিধা ও অসুবিধার কথা চিন্তা করে।","a":"সত্য"}],"match":[{"n":"১","q":"দৃষ্টি প্রতিবন্ধিতা","a":"দেখতে অসুবিধা"},{"n":"২","q":"বুদ্ধি প্রতিবন্ধিতা","a":"একই কাজ একটানা করতে থাকা"},{"n":"৩","q":"শ্রবণ প্রতিবন্ধিতা","a":"শুনতে অসুবিধা"},{"n":"৪","q":"বাক প্রতিবন্ধিতা","a":"কথা বলায় অসুবিধা"}],"short":[{"n":"১","q":"অটিস্টিক শিশুর তিনটি বৈশিষ্ট্য লেখ।","a":"অটিস্টিক শিশুর তিনটি বৈশিষ্ট্য:\n• এরা কোনো একটি নির্দিষ্ট বস্তুর প্রতি প্রবল আকর্ষণ অনুভব করে।\n• অটিস্টিক শিশুরা সাধারণত একই কাজ একটানা করতে থাকে।\n• কথা বলার সময় এরা অন্যের চোখের দিকে তাকিয়ে কথা বলে না।"},{"n":"২","q":"বিদ্যালয়ে মিলেমিশে কাজ করার তিনটি সুবিধা লেখ।","a":"বিদ্যালয়ে মিলেমিশে কাজ করার তিনটি সুবিধা:\n• বিদ্যালয়ে সবার উপযোগী কাজ মিলেমিশে করলে কাজের পরিবেশ অনেক সুন্দর হয়।\n• শিক্ষার্থীদের মধ্যে পারস্পরিক সম্মানবোধ তৈরি হয় এবং কেউ নিজেকে অবহেলিত মনে করে না।\n• শিক্ষার্থীরা একে অপরের সুবিধা ও অসুবিধার কথা চিন্তা করতে শেখে এবং যেকোনো সমস্যা একে অপরের সহযোগিতায় সহজে বুঝতে পারে।"}],"essay":[{"n":"১","q":"শ্রবণ ও বাক সমস্যাগ্রস্ত সহপাঠীকে তুমি কীভাবে সহযোগিতা করবে?","a":"শ্রবণ ও বাক সমস্যাগ্রস্ত সহপাঠীকে আমি যেভাবে সহযোগিতা করব, তা নিচে বর্ণনা করা হলো:\n• তার সাথে কথা বলার সময় ইশারা ও অঙ্গভঙ্গির সাহায্য নেব যাতে সে সহজেই বিষয়টি বুঝতে পারে।\n• তাকে কোনো নির্দেশনা দেওয়ার সময় সেটি মুখে বলার পাশাপাশি লিখে দেওয়ার চেষ্টা করব।\n• তার সাথে খুব দ্রুত কথা না বলে ধীরগতিতে কথা বলব।\n• সে যেন শিক্ষকের পাঠদান ভালোভাবে শুনতে পায়, সেজন্য তাকে শ্রেণিকক্ষের সামনের দিকে বসতে সহায়তা করব।\n• তার কথাগুলো মনোযোগের সাথে শোনার চেষ্টা করব এবং তাকে বুঝতে না পারলে ধৈর্য সহকারে বারবার বোঝার চেষ্টা করব।\n• তাকে সব সময় ভালো আচরণ করব এবং সে যেন কোনো কারণে রাগ বা কষ্ট না পায় সেদিকে খেয়াল রাখব।"}]}},{"no":3,"title":"বাংলদেশের ক্ষুদ্র নৃগোষ্ঠী","q":{"mcq":[{"n":"১","q":"গারোদের নিজস্ব ভাষা কোনটি?","a":"ক) আচিক","o":["আচিক","মনখেমে","কুরুখ","সাদরি"]},{"n":"২","q":"নিচের কোন নৃগোষ্ঠী বান্দরবান জেলায় বসবাস করে?","a":"গ) ম্রো","o":["গারো","খাসি","ম্রো","সাঁওতাল"]},{"n":"৩","q":"সাঁওতালদের প্রধান উৎসব-","a":"খ) সোহরাই","o":["চাংক্রান","সোহরাই","কারাম","ওয়ানগালা"]}],"blank":[{"n":"১","q":"খাসি সমাজ ______।","a":"মাতৃতান্ত্রিক"},{"n":"২","q":"২ ম্রো নৃগোষ্ঠীর জীবনধারণের জন্য ______ চাষ করে।","a":"জুম"},{"n":"৩","q":"গারোদের বিশেষভাবে তৈরি ______ নাম নকমান্দি।","a":"বাড়ির"},{"n":"৪","q":"আমরা সকল ক্ষুদ্র নৃগোষ্ঠীর প্রতি ______ করব।","a":"শ্রদ্ধা পোষণ"}],"match":[{"n":"১","q":"গারোদের উৎসব","a":"ওয়ানগালা"},{"n":"২","q":"ম্রোদের উৎসব","a":"চাংক্রান"},{"n":"৩","q":"ওঁরাওদের উৎসব","a":"কারাম"},{"n":"৪","q":"খাসিদের উৎসব","a":"সেং কুটস্নেম"}],"short":[{"n":"১","q":"ওঁরাও জনগোষ্ঠীর তিনটি খাবার ও পোশাকের নাম লেখ।","a":"ওঁরাও জনগোষ্ঠীর তিনটি খাবার ও পোশাকের নাম:\n• তিনটি খাবারের নাম: ভাত, মাছ এবং মাংস। (এছাড়াও তারা ডাল ও বিভিন্ন ধরনের শাকসবজি খেয়ে থাকে)।\n• তিনটি পোশাকের নাম: ধুতি, লুঙ্গি এবং শাড়ি। (পুরুষেরা ধুতি ও লুঙ্গি এবং নারীরা শাড়ি পরিধান করেন)।"},{"n":"২","q":"গারো নৃগোষ্ঠী বাংলাদেশের কোন কোন জেলায় বাস করে?","a":"গারো নৃগোষ্ঠী প্রধানত বাংলাদেশের ময়মনসিংহ, টাঙ্গাইল, নেত্রকোনা ও শেরপুর জেলায় বসবাস করে।"}],"essay":[{"n":"১","q":"খাসি ক্ষুদ্র নৃগোষ্ঠীর জীবনধারা বর্ণনা করো।","a":"খাসি ক্ষুদ্র নৃগোষ্ঠী প্রধানত বাংলাদেশের সিলেট অঞ্চলের বিভিন্ন এলাকায় বসবাস করে। তাদের সমাজব্যবস্থা মাতৃতান্ত্রিক, যেখানে পরিবারের সম্পত্তির উত্তরাধিকারী হয় পরিবারের সবচেয়ে ছোট মেয়ে। তারা মূলত কৃষিজীবী এবং প্রচুর পরিমাণে পান ও সুপারি চাষ করে থাকে। খাসিদের নিজস্ব ভাষার নাম 'মনখেমে', যার কোনো লিখিত বর্ণমালা নেই। খাদ্যাভ্যাসের দিক থেকে তারা ভাত, মাছ, মাংস ও শুঁটকি মাছ পছন্দ করে এবং পান-সুপারি ও চা তাদের সংস্কৃতির অন্যতম অংশ। তাদের পোশাকও বেশ বৈচিত্র‍্যময়; নারীরা 'কাজিম পিন' নামক ব্লাউজ ও লুঙ্গি পরেন এবং পুরুষেরা 'ফুং মারুং' নামক পকেট ছাড়া শার্ট ও লুঙ্গি পরিধান করেন।"},{"n":"২","q":"বাংলাদেশের সাঁওতাল ও ম্রো ক্ষুদ্র নৃগোষ্ঠীর সাংস্কৃতিক বৈশিষ্ট্য বর্ণনা করো।","a":"সাঁওতাল ও ম্রো উভয় নৃগোষ্ঠীরই নিজস্ব ও স্বতন্ত্র সাংস্কৃতিক ঐতিহ্য রয়েছে। সাঁওতালরা প্রধানত কৃষিনির্ভর এবং তারা অত্যন্ত পরিষ্কার-পরিচ্ছন্ন ও অতিথিপরায়ণ হিসেবে পরিচিত। তাদের প্রধান উৎসবের নাম 'সোহরাই', যা ফসল তোলার পর পৌষ মাসে উদ্‌যাপন করা হয়। সাঁওতাল নারীরা 'পানচি' ও 'পাডহাহাট' নামক দুই খ- কাপড় পরেন এবং পুরুষেরা ধুতি বা লুঙ্গি ব্যবহার করেন। অন্যদিকে, ম্রোরা প্রধানত বান্দরবান জেলায় বসবাস করে এবং জুম চাষের মাধ্যমে জীবিকা নির্বাহ করে। ম্রোদের নিজস্ব ভাষা ও বর্ণমালা রয়েছে এবং তারা সৃষ্টিকর্তাকে 'থোরাই' নামে ডাকে। তাদের প্রধান উৎসব হলো বর্ষবরণের 'চাংক্রান'। ম্রো নারীদের ঐতিহ্যবাহী পোশাকের নাম 'ওয়াংলাই' এবং পুরুষেরা 'দংকেন' নামক খাটো সাদা পোশাক পরে থাকেন। তাদের খাদ্যাভ্যাসের একটি বিশেষ বৈশিষ্ট্য হলো 'নাপ্পি' নামক এক প্রকার উপাদানের ব্যবহার।"}]}},{"no":4,"title":"আমাদের স্মরণীয় নেতা","q":{"mcq":[{"n":"১","q":"অবিভক্ত বাংলার প্রথম নির্বাচিত প্রধানমন্ত্রী কে?","a":"ক) শেরে বাংলা এ কে ফজলুল হক","o":["শেরে বাংলা এ কে ফজলুল হক","মওলানা আবদুল হামিদ খান ভাসানী","হোসেন শহীদ সোহ্রাওয়ার্দী","শেখ মুজিবুর রহমান"]},{"n":"২","q":"মওলানা আবদুল হামিদ খান ভাসানী কী হিসেবে সর্বাধিক পরিচিত?","a":"খ) মজলুম জননেতা","o":["বাংলার বাঘ","মজলুম জননেতা","অবিসংবাদী নেতা","রাজনীতিবিদ"]}],"blank":[{"n":"১","q":"ঋণের অত্যাচার থেকে ______ বাঁচানোর জন্য ঋণ সালিশি বোর্ড গঠন করা হয়।","a":"কৃষকদের"},{"n":"২","q":"মওলানা আবদুল হামিদ খান ভাসানচরে কৃষকদের জন্য ______ ভিত্তিতে একটি বাঁধ নির্মাণ করেন।","a":"স্বেচ্ছাশ্রমের"},{"n":"৩","q":"হোসেন শহীদ সোহ্‌রাওয়ার্দী ______ গঠনে প্রধান ভূমিকা পালন করেন।","a":"যুক্তফ্রন্ট"}],"match":[{"n":"১","q":"এ কে ফজলুল হক","a":"বাংলার বাঘ"},{"n":"২","q":"আবদুল হামিদ খান ভাসানী","a":"মজলুম নেতা"},{"n":"৩","q":"হোসেন শহীদ সোহ্‌রাওয়ার্দী","a":"শ্রমিকনেতা ট্রেড ইউনিয়ন গঠন"},{"n":"৪","q":"শেখ মুজিবুর রহমান","a":"বঙ্গবন্ধু"}],"short":[{"n":"১","q":"ঋণ সালিশি বোর্ড কেন গঠন করা হয়েছিল?","a":"তৎকালীন সময়ে এদেশের সাধারণ কৃষকরা মহাজনদের ঋণের জালে জর্জরিত ছিল। এই মহাজনদের ঋণের অত্যাচার থেকে কৃষকদের বাঁচানোর জন্য এবং তাদের দুঃখ দূর করার লক্ষ্যেই শেরে বাংলা এ কে ফজলুল হক ঋণ সালিশি বোর্ড গঠন করেছিলেন।"},{"n":"২","q":"মওলানা আবদুল হামিদ খানকে কেন 'ভাসানী' উপাধি দেয়া হয়?","a":"ত্রিশের দশকের শেষদিকে আসামের ঘাগমারায় বসবাসকারী বাঙালিদের স্বার্থরক্ষার আন্দোলনে মওলানা ভাসানী নেতৃত্ব দেন। সেই সময় ঐ এলাকায় ব্রহ্মপুত্র নদীর ভাসানচরে বন্যার কবল থেকে বাঙালি কৃষকদের রক্ষার জন্য তিনি স্বেচ্ছাশ্রমের ভিত্তিতে একটি বাঁধ নির্মাণ করেন। তাঁর এই মহান অবদানের স্বীকৃতিস্বরূপ সেখানকার সাধারণ মানুষ তাঁকে 'ভাসানী' উপাধি দিয়ে সম্মান জানায়।"}],"essay":[{"n":"১","q":"ইতিহাসে স্মরণীয় নেতাদের জীবনী থেকে কী কী আদর্শ গ্রহণ করতে পারো তা বর্ণনা করো।","a":"ইতিহাসে স্মরণীয় নেতা যেমন—শেরে বাংলা এ কে ফজলুল হক, মওলানা আবদুল হামিদ খান ভাসানী, হোসেন শহীদ সোহ্‌রাওয়ার্দী এবং বঙ্গবন্ধু শেখ মুজিবুর রহমানের জীবনী থেকে আমরা অনেক গুরুত্বপূর্ণ আদর্শ গ্রহণ করতে পারি। নিচে সেগুলো বর্ণনা করা হলো:\n• অন্যায়ের বিরুদ্ধে প্রতিবাদ ও সাহসিকতা: সকল নেতাই শোষক ও অন্যায়কারীর বিরুদ্ধে সাহসী ভূমিকা পালন করেছেন। তাঁদের মতো যেকোনো অন্যায়ের বিরুদ্ধে আপসহীন থাকার আদর্শ আমরা গ্রহণ করতে পারি।\n• দেশপ্রেম ও আত্মত্যাগ: দেশের মানুষের অধিকার আদায়ে তাঁরা বারবার কারাবরণ করেছেন এবং ব্যক্তিগত সুখ-সুবিধা ত্যাগ করেছেন। তাঁদের এই নিঃস্বার্থ দেশপ্রেম আমাদের দেশ গড়ার কাজে অনুপ্রাণিত করে।\n• সাধারণ মানুষের প্রতি ভালোবাসা: শেরে বাংলার কৃষকদের প্রতি মমতা, মওলানা ভাসানীর মজলুম মানুষের সেবা কিংবা সোহ্রাওয়ার্দীর মেহনতি মানুষের সংগঠন গড়ার ঘটনাগুলো আমাদের সাধারণ মানুষের কল্যাণে কাজ করার শিক্ষা দেয়।\n• সাম্প্রদায়িক সম্প্রীতি ও ঐক্য: হোসেন শহীদ সোহ্‌রাওয়ার্দী ও বঙ্গবন্ধু শেখ মুজিবুর রহমান আজীবন সকল জাতি ও ধর্মের মানুষের অধিকার রক্ষা এবং সংহতি বজায় রাখার কাজ করেছেন। জাতি-ধর্ম নির্বিশেষে মিলেমিশে থাকার আদর্শ এখান থেকে পাওয়া যায়।\n• শিক্ষার গুরুত্ব উপলব্ধি: শেরে বাংলা ও মওলানা ভাসানী এদেশের সাধারণ মানুষের শিক্ষার জন্য বহু স্কুল, কলেজ ও মাদ্রাসা প্রতিষ্ঠা করেছেন। এটি আমাদের জীবনে শিক্ষার আলোকবর্তিকা ছড়িয়ে দেওয়ার প্রেরণা যোগায়।\n• গণতান্ত্রিক মূল্যবোধ: হোসেন শহীদ সোহ্‌রাওয়ার্দী 'গণতন্ত্রের অতন্দ্র প্রহরী' হিসেবে মানুষের ভোটের অধিকার ও গণতান্ত্রিক পরিবেশ নিশ্চিত করতে সংগ্রাম করেছেন। এই আদর্শ থেকে আমরা পরমতসহিষ্ণুতা ও গণতন্ত্রের চর্চা শিখতে পারি।\nস্মরণীয় এই নেতাদের আদর্শগুলো আমাদের ব্যক্তিগত ও সামাজিক জীবনে প্রতিফলিত হলে আমরা একটি সুন্দর ও বৈষম্যহীন দেশ গড়তে পারব।"}]}},{"no":5,"title":"আমাদের মুক্তিযুদ্ধ","q":{"mcq":[{"n":"১","q":"মুক্তিযুদ্ধ পরিচালনার জন্য সমগ্র দেশকে কয়টি সেক্টরে ভাগ করা হয়?","a":"গ) ১১টি","o":["৯টি","১০টি","১১টি","১২টি"]},{"n":"২","q":"পাকিস্তান সৃষ্টির পরে শাসক গোষ্ঠী প্রথমেই আঘাত করে কীসের উপর?","a":"খ) বাংলা ভাষার উপর","o":["বাংলার অর্থনীতির উপর","বাংলা ভাষার উপর","বাংলার রাজনীতির উপর","বাংলার প্রশাসনের উপর"]},{"n":"৩","q":"কোন বাহিনী 'অপারেশন জ্যাকপট' অভিযান পরিচালনা করে?","a":"ক) নৌবাহিনী","o":["নৌবাহিনী","বিমানবাহিনী","সেনাবাহিনী","পুলিশবাহিনী"]}],"blank":[{"n":"১","q":"'অপারেশন সার্চলাইট' বাংলাদেশের ইতিহাসে ______ নামে পরিচিত।","a":"কালো রাত"},{"n":"২","q":"নারী মুক্তিযোদ্ধাদের মধ্যে দুজনে ______ খেতাবপ্রাপ্ত।","a":"বীরপ্রতীক"}],"match":[{"n":"১","q":"১৯৭১ সালের ২৬শে মার্চ","a":"স্বাধীনতার ঘোষণা"},{"n":"২","q":"১৯৭১ সালের ১০ই এপ্রিল","a":"বাংলাদেশের প্রথম সরকার"},{"n":"৩","q":"১৯৭১ সালের ১৭ই এপ্রিল","a":"প্রথম সরকারের শপথ গ্রহণ"},{"n":"৪","q":"১৯৭১ সালের ১৬ই ডিসেম্বর","a":"মুক্তিযুদ্ধে চূড়ান্ত বিজয় অর্জন"}],"short":[{"n":"১","q":"মুক্তিবাহিনী কাদের সমন্বয়ে গঠিত হয়?","a":"১৯৭১ সালের মহান মুক্তিযুদ্ধে ছাত্র, যুবক, কৃষক, শ্রমিক, পুলিশ, তৎকালীন ইপিআর (ইস্ট পাকিস্তান রাইফেলস) এবং সামরিক বাহিনীর সদস্যদের সমন্বয়ে মুক্তিবাহিনী গঠিত হয়।"},{"n":"২","q":"মুক্তিযোদ্ধাদের বীরত্বসূচক রাষ্ট্রীয় খেতাবগুলোর নাম লেখ।","a":"মুক্তিযুদ্ধে অসীম সাহসিকতা ও বীরত্ব প্রদর্শনের জন্য বাংলাদেশ সরকার ৪টি বীরত্বসূচক রাষ্ট্রীয় খেতাব প্রদান করে। সেগুলো হলো:\n• বীর শ্রেষ্ঠ (সর্বোচ্চ খেতাব)\n• বীর উত্তম\n• বীর বিক্রম\n• বীর প্রতীক"}],"essay":[{"n":"১","q":"মুক্তিযুদ্ধে সাধারণ মানুষের অবদান বর্ণনা করো।","a":"১৯৭১ সালের মহান মুক্তিযুদ্ধ ছিল একটি প্রকৃত 'জনযুদ্ধ'। এই যুদ্ধে সর্বস্তরের সাধারণ মানুষের অবদান ছিল অপরিসীম:\n• সরাসরি অংশগ্রহণ: ছাত্র, যুবক, কৃষক ও শ্রমিকরা সামান্য প্রশিক্ষণ নিয়ে সম্মুখ যুদ্ধে এবং গেরিলা আক্রমণে অংশ নিয়েছেন। তাঁরা আধুনিক অস্ত্রশস্ত্রে সজ্জিত পাকিস্তানি বাহিনীকে নাজেহাল করে তুলেছিলেন।\n• আশ্রয় ও তথ্য প্রদান: গ্রামের সাধারণ মানুষ নিজেদের জীবনের ঝুঁকি নিয়ে মুক্তিযোদ্ধাদের আশ্রয় দিয়েছেন। তাঁরা পাকিস্তানি বাহিনীর অবস্থান ও গতিবিধি সম্পর্কে মুক্তিযোদ্ধাদের গোপন সংবাদ দিয়ে সাহায্য করেছেন।\n• সেবা ও খাবার সরবরাহ: সাধারণ মানুষ মুক্তিযোদ্ধাদের খাবার ও প্রয়োজনীয় চিকিৎসা সেবা দিয়েছেন। নারীরা মুক্তিযোদ্ধাদের জন্য খাবার রান্না করা, জামা-কাপড় সংগ্রহ এবং আহতদের সেবা-শুশ্রূষা করার মাধ্যমে গুরুত্বপূর্ণ ভূমিকা পালন করেছেন।\n• সাংস্কৃতিক অনুপ্রেরণা: কবি, শিল্পী ও সাহিত্যিকরা তাঁদের গান ও লেখনীর মাধ্যমে মুক্তিযোদ্ধাদের সাহস ও দেশপ্রেম বাড়িয়ে তুলেছিলেন।\n• সম্মিলিত ত্যাগ: সাধারণ মানুষের এই স্বতঃস্ফূর্ত সমর্থন ও আত্মত্যাগ ছাড়া মাত্র ৯ মাসে বিজয় অর্জন করা অসম্ভব ছিল।"},{"n":"২","q":"তোমরা কীভাবে বিদ্যালয়ে বিজয় দিবস উদযাপন করো সে সম্পর্কে লেখ।","a":"প্রতি বছর ১৬ই ডিসেম্বর আমাদের বিদ্যালয়ে অত্যন্ত আনন্দ ও শ্রদ্ধার সাথে বিজয় দিবস উদযাপন করা হয়। আমাদের উদযাপনের প্রক্রিয়াটি নিচে বর্ণনা করা হলো:\n• সাজসজ্জা: বিজয় দিবসের আগের দিন বিকেলে আমরা শিক্ষকের সহায়তায় বিদ্যালয় প্রাঙ্গণ ও শ্রেণিকক্ষ রঙিন কাগজ ও পতাকা দিয়ে সাজাই।\n• বিজয় র্যালী ও শ্রদ্ধা নিবেদন: ১৬ই ডিসেম্বর সকালে আমরা শিক্ষক ও শিক্ষার্থীরা মিলে 'বিজয় র্যালী' করি এবং স্থানীয় স্মৃতিসৌধে পুষ্পস্তবক অর্পণের মাধ্যমে শহীদদের প্রতি শ্রদ্ধা জানাই।\n• জাতীয় পতাকা উত্তোলন: সকাল সাড়ে আটটায় প্রধান শিক্ষক মহোদয় জাতীয় সংগীত গাওয়ার মাধ্যমে আনুষ্ঠানিকভাবে জাতীয় পতাকা উত্তোলন করেন।\n• আলোচনা সভা ও সাংস্কৃতিক অনুষ্ঠান: বিদ্যালয়ের অডিটোরিয়ামে মুক্তিযুদ্ধের গল্প বলা এবং আলোচনা সভা অনুষ্ঠিত হয়। এরপর আমরা দেশাত্মবোধক গান, কবিতা আবৃত্তি এবং নাটিকা পরিবেশন করি।\n• ক্রীড়া ও পুরস্কার বিতরণ: দিনটি উপলক্ষে বিশেষ ক্রীড়া প্রতিযোগিতা ও চিত্রাঙ্কন প্রতিযোগিতার আয়োজন করা হয়। অনুষ্ঠানের শেষে বিজয়ীদের হাতে পুরস্কার তুলে দেওয়া হয়।"}]}},{"no":6,"title":"বাংলাদেশের ঐতিহাসিক স্থান ও নিদর্শন","q":{"mcq":[{"n":"১","q":"মহাস্থানগড় কোন নদীর তীরে অবস্থিত?","a":"ক) করতোয়া","o":["করতোয়া","শীতলক্ষ্যা","বুড়িগঙ্গা","ইছামতি"]},{"n":"২","q":"নিচের কোন সভ্যতা সমুদ্র বাণিজ্যের সাথে সম্পর্কিত?","a":"গ) উয়ারী-বটেশ্বর","o":["মহাস্থানগড়","ময়নামতি","উয়ারী-বটেশ্বর","পাহাড়পুর"]},{"n":"৩","q":"'ময়লা আবর্জনা নির্দিষ্ট স্থানে ফেলবেন' প্রত্নতাত্ত্বিক স্থানে এই লেখাটি থাকে কেন?","a":"খ) পরিবেশ পরিচ্ছন্ন রাখা","o":["সৌন্দর্য বর্ধন","পরিবেশ পরিচ্ছন্ন রাখা","পর্যটকের দৃষ্টি আকর্ষণ","শৃঙ্খলা রক্ষা করা"]}],"blank":[{"n":"১","q":"লালবাগ কেল্লার প্রথম নাম ______।","a":"কেল্লা আওরাঙ্গবাদ"},{"n":"২","q":"প্রাচীন বাংলার মুসলিম সুলতানদের রাজধানী ______।","a":"সোনার গাঁও"}],"match":[{"n":"১","q":"পাহাড়পুর","a":"নওগাঁ"},{"n":"২","q":"ময়নামতি","a":"কুমিল্লা"},{"n":"৩","q":"পানামনগর","a":"নারায়ণগঞ্জ"},{"n":"৪","q":"লালবাগ কেল্লা","a":"ঢাকা"}],"short":[{"n":"১","q":"উয়ারী-বটেশ্বরে প্রাপ্ত তিনটি নিদর্শনের নাম লেখ।","a":"উয়ারী-বটেশ্বরে প্রাপ্ত উল্লেখযোগ্য তিনটি নিদর্শনের নাম হলো-ছাপাঙ্কিত রৌপ্যমুদ্রা, পাথরের পুঁতি এবং লোহার তৈরি হাতিয়ার।"},{"n":"২","q":"পানামনগর কীভাবে বাণিজ্য কেন্দ্রে পরিণত হয়েছিল?","a":"উনবিংশ শতাব্দীতে হিন্দু বণিকরা পানামনগরকে কেন্দ্র করে মূলত সুতি বস্ত্রের (মসলিন ও নীল) ব্যবসা শুরু করেন। মেঘনা নদীর নিকটবর্তী হওয়ায় জলপথে যাতায়াতের সুবিধা এবং স্থানীয়ভাবে উৎপাদিত উন্নত সুতার ব্যবসার কারণেই এটি একটি শক্তিশালী বাণিজ্য কেন্দ্রে পরিণত হয়েছিল।"}],"essay":[{"n":"১","q":"ঐতিহাসিক স্থান ও নিদর্শন সংরক্ষণ করা প্রয়োজন কেন?","a":"ঐতিহাসিক স্থান ও নিদর্শনগুলো একটি জাতির শেকড় এবং পরিচয় বহন করে। এগুলো সংরক্ষণ করা কেন প্রয়োজন, তার প্রধান কারণগুলো নিচে আলোচনা করা হলো:\n• ইতিহাসের নির্ভরযোগ্য প্রমাণ: বই পড়ে ইতিহাস জানা যায়, কিন্তু ঐতিহাসিক স্থান ও নিদর্শনগুলো সেই ইতিহাসকে আমাদের চোখের সামনে জীবন্ত করে তোলে। এগুলো অতীত সভ্যতার সামাজিক, রাজনৈতিক ও অর্থনৈতিক অবস্থার বাস্তব সাক্ষ্য। যেমন: মহাস্থানগড় বা লালবাগ কেল্লা দেখলে আমরা প্রাচীন শাসনব্যবস্থা ও স্থাপত্যশৈলী সম্পর্কে সঠিক ধারণা পাই।\n• সাংস্কৃতিক ঐতিহ্য ও জাতীয় পরিচয়: একটি জাতি কতটুকু সমৃদ্ধ ছিল, তা তাদের প্রাচীন স্থাপত্য ও শিল্পকলা দেখে বোঝা যায়। এগুলো আমাদের জাতীয় গর্ব এবং বিশ্ব দরবারে আমাদের স্বকীয়তা তুলে ধরে। এগুলো হারিয়ে গেলে জাতি হিসেবে আমরা আমাদের গৌরবের ইতিহাস ভুলে যাব।\n• শিক্ষা ও গবেষণা: প্রত্নতত্ত্ববিদ ও ইতিহাসবিদদের জন্য এই নিদর্শনগুলো গবেষণার প্রধান উৎস। প্রাচীন লিপিমালা, মুদ্রা বা স্থাপত্যকলা বিশ্লেষণ করে অজানাকে জানা সম্ভব হয়। এছাড়া নতুন প্রজন্মের শিক্ষার্থীদের কাছে সঠিক ইতিহাস পৌঁছে দেওয়ার জন্য এগুলো সংরক্ষণ করা জরুরি।\n• অর্থনৈতিক গুরুত্ব: ঐতিহাসিক স্থানগুলো পর্যটনের প্রধান আকর্ষণ। দেশি-বিদেশি পর্যটকরা এসব স্থান পরিদর্শনে এলে দেশের রাজস্ব আয় বৃদ্ধি পায় এবং স্থানীয় মানুষের কর্মসংস্থানের সুযোগ সৃষ্টি হয়।\nসুতরাং, আমাদের ঐতিহ্যকে বিলীন হওয়ার হাত থেকে বাঁচাতে এবং ভবিষ্যৎ প্রজন্মের জন্য জ্ঞান ও সমৃদ্ধির উৎস হিসেবে এগুলো সংরক্ষণ করা একান্ত প্রয়োজন।"},{"n":"২","q":"ঐতিহাসিক স্থান সংরক্ষণে তোমার করণীয় কী?","a":"ঐতিহাসিক স্থানগুলো আমাদের অমূল্য সম্পদ, তাই এগুলো রক্ষায় একজন সচেতন নাগরিক হিসেবে আমার অনেক কিছু করার আছে। আমার করণীয়গুলো নিচে তুলে ধরা হলো:\n• সচেতনতা অবলম্বন: আমি যখন কোনো ঐতিহাসিক স্থানে ভ্রমণে যাব, তখন সেখানকার নিয়মকানুন কঠোরভাবে মেনে চলব। অনেক সময় দেখা যায় দর্শনার্থীরা অতি উৎসাহী হয়ে প্রাচীন দেয়ালে নাম লেখেন বা পাথর দিয়ে দাগ কাটেন। আমি নিজে কখনও এমন কাজ করব না এবং অন্য কেউ করলে তাকে বিনয়ের সাথে বাধা দেব।\n• নিদর্শন স্পর্শ না করা: প্রাচীন স্থাপনাগুলো সাধারণত নাজুক ইটের বা মাটির তৈরি হয়। মানুষের হাতের স্পর্শে বা বারবার ঘর্ষণে নিদর্শনের ক্ষয় হতে পারে। তাই আমি কোনো প্রত্নতাত্ত্বিক বস্তু বা মূর্তি স্পর্শ করব না এবং নির্দিষ্ট দূরত্ব বজায় রেখে পর্যবেক্ষণ করব।\n• পরিবেশ রক্ষা: প্রত্নতাত্ত্বিক এলাকার ভেতর খাবার বা প্লাস্টিকের প্যাকেট, বোতল ইত্যাদি যেখানে-সেখানে ফেলব না। নির্দিষ্ট ডাস্টবিনে ময়লা ফেলে এলাকাটি পরিষ্কার রাখব, যাতে নিদর্শনের পরিবেশ নষ্ট না হয়।\n• প্রচার ও উদ্বুদ্ধকরণ: আমি আমার বন্ধুদের এবং পরিবারের সদস্যদের ঐতিহাসিক নিদর্শনের গুরুত্ব সম্পর্কে জানাব। সামাজিক যোগাযোগ মাধ্যম বা বিদ্যালয়ের দেয়ালিকায় প্রবন্ধ লিখে এই সম্পদগুলো রক্ষার প্রয়োজনীয়তা নিয়ে জনসচেতনতা তৈরি করব।\n• কর্তৃপক্ষকে সহযোগিতা: যদি দেখি কোনো স্থাপত্যের অংশ ভেঙে পড়ছে বা কেউ চুরি করার চেষ্টা করছে, তবে তাৎক্ষণিকভাবে দায়িত্বরত কর্মকর্তা বা স্থানীয় প্রশাসনকে অবহিত করব।\nআমাদের ছোট ছোট এই সচেতন পদক্ষেপগুলোই পারে হাজার বছরের পুরনো এই ঐতিহ্যগুলোকে শতাব্দীর পর শতাব্দী বাঁচিয়ে রাখতে।"}]}},{"no":7,"title":"দক্ষিণ এশিয়ার সাংস্কৃতিক বৈশিষ্ট্য","q":{"mcq":[{"n":"১","q":"বাংলাদেশের প্রচলিত খাবার কোনটি?","a":"খ) ভাত-মাছ","o":["পোলাও-মাংস","ভাত-মাছ","বিরিয়ানি কোরমা","রুটি-মাংস"]},{"n":"২","q":"ভুটানের রাষ্ট্রীয় ভাষা কী?","a":"ঘ) জংখা","o":["হিন্দি","উর্দু","পশতু","জংখা"]},{"n":"৩","q":"মালদ্বীপের প্রধান ধর্মীয় উৎসব কোনটি?","a":"ক) ঈদ","o":["ঈদ","দুর্গাপূজা","বড়োদিন","বুদ্ধপূর্ণিমা"]}],"truefalse":[{"n":"১","q":"কিরিবাথ হলো ভাত ও চিংড়ি দিয়ে তৈরি শ্রীলঙ্কান একটি খাবার।","a":"সত্য"},{"n":"২","q":"রুটি, মাংস নেপালের মানুষের প্রধান খাবার।","a":"MISSING","e":"বইয়ে উত্তর-চিহ্ন \"অ\" ছাপা আছে"},{"n":"৩","q":"নতুন ধান ঘরে তোলার সময় বাংলাদেশিরা নবান্ন উৎসব পালন করে।","a":"সত্য"}],"match":[{"n":"১","q":"বাংলাদেশ","a":"বাংলা"},{"n":"২","q":"আফগানিস্তান","a":"পশতু"},{"n":"৩","q":"পাকিস্তান","a":"উর্দু"},{"n":"৪","q":"ভারত","a":"হিন্দি"}],"short":[{"n":"১","q":"বাংলাদেশের ভূখ-ের সাথে সংযুক্ত দেশগুলোর নাম লেখ।","a":"বাংলাদেশের ভূখ-ের সাথে সংযুক্ত দুটি প্রতিবেশী দেশ হলো ভারত এবং মিয়ানমার। ভারতের সাথে বাংলাদেশের দীর্ঘ সীমান্ত রয়েছে এবং দক্ষিণ-পূর্বে মিয়ানমারের সাথে ক্ষুদ্র সীমানা রয়েছে।"},{"n":"২","q":"আফগানিস্তানের মানুষ কী কী পোশাক পরিধান করে?","a":"আফগানিস্তানের মানুষের ঐতিহ্যবাহী পোশাক ঢিলেঢালা ফিটিং কুর্তা ও পায়জামা। নারীরা বোরকা ও মাথায় হিজাব পরে। সবচেয়ে জনপ্রিয় ঐতিহ্যবাহী পোশাকের মধ্যে রয়েছে পশতুন পোশাক।"}],"essay":[{"n":"১","q":"বাংলাদেশের সাথে ভারত ও পাকিস্তানের সংস্কৃতির যেসব মিল আছে তা উল্লেখ করো।","a":"বাংলাদেশ, ভারত এবং পাকিস্তান-এই তিনটি দেশই দক্ষিণ এশিয়ায় অবস্থিত এবং দীর্ঘ সময় একই ভূখ-ের অন্তর্ভুক্ত ছিল। এই ভৌগোলিক ও ঐতিহাসিক নৈকট্যের কারণে এদের সংস্কৃতির মধ্যে অনেক গভীর মিল লক্ষ্য করা যায়। নিচে প্রধান মিলগুলো আলোচনা করা হলো:\n• খাদ্যাভ্যাস: তিনটি দেশের মানুষের প্রধান খাবারের তালিকায় ভাত ও রুটির প্রাধান্য দেখা যায়। ডাল, বিভিন্ন রকমের সবজি, মাছ ও মাংস এই তিন দেশের সাধারণ মানুষের নিয়মিত খাবারের অংশ। এছাড়া বিরিয়ানি, পোলাও, কোরমা এবং বিভিন্ন ধরনের কাবাব বা টিক্কা এই তিন দেশেই সমান জনপ্রিয়। মিষ্টি জাতীয় খাবারের ক্ষেত্রেও তিন দেশেই নানা রকম ঐতিহ্যবাহী পিঠা ও মিষ্টির প্রচলন আছে।\n• পোশাক-আশাক: পোশাকের ক্ষেত্রেও এই তিন দেশের মধ্যে লক্ষ্যণীয় মিল রয়েছে। যেমন-নারীদের প্রধান পোশাক হিসেবে 'শাড়ি' বাংলাদেশ ও ভারতে বহুল প্রচলিত, আবার 'সালোয়ার-কামিজ' বাংলাদেশ, ভারত ও পাকিস্তান-তিন দেশের নারীদের মধ্যেই অত্যন্ত জনপ্রিয়। পুরুষদের ক্ষেত্রে লুঙ্গি এবং পাঞ্জাবি-পায়জামার ব্যবহার তিনটি দেশেই দেখা যায়।\n• ভাষা: যদিও প্রতিটি দেশের নিজস্ব প্রধান ভাষা আলাদা, তবুও ভাষার শিকড়ে অনেক মিল রয়েছে। যেমন-ভারতে বাংলার পাশাপাশি হিন্দি ও উর্দু প্রচলিত, যা পাকিস্তান ও বাংলাদেশের অনেক মানুষের কাছেই বোধগম্য।\n• উৎসব: উৎসব পালনের ক্ষেত্রে ধর্মীয় মিলগুলো স্পষ্টভাবে ফুটে ওঠে। তিন দেশের মুসলিম সম্প্রদায়ই ঈদুল ফিতর ও ঈদুল আজহা অত্যন্ত গুরুত্বের সাথে পালন করে। এছাড়া বিভিন্ন ঋতুভিত্তিক মেলা ও সামাজিক অনুষ্ঠান পালনের রীতিও অনেকটা একই রকম।"},{"n":"২","q":"নেপালে বেড়াতে গিয়ে তাদের সংস্কৃতির প্রতি তুমি কীভাবে শ্রদ্ধাশীল আচরণ করবে?","a":"নেপাল একটি বহু জাতিগোষ্ঠীর দেশ, যেখানে বৈচিত্র‍্যময় সংস্কৃতি ও ধর্মীয় রীতিনীতি বিদ্যমান। নেপালে ভ্রমণকালে তাদের সংস্কৃতির প্রতি শ্রদ্ধাশীল হতে আমি নিচের ভূমিকাগুলো পালন করব:\n• ধর্মীয় স্থানের নিয়মাবলী মেনে চলা: নেপাল মন্দির ও স্তূপের দেশ। যেকোনো মন্দির বা পবিত্র স্থানে প্রবেশের সময় জুতো বাইরে রেখে প্রবেশ করব। মন্দির বা উপাসনালয়ের ভেতরে ছবি তোলার ক্ষেত্রে নিষেধাজ্ঞা থাকলে তা কঠোরভাবে মেনে চলব।\n• পোশাকের সর্তকতা: নেপালিরা সাধারণত মার্জিত পোশাকে অভ্যস্ত। তাদের জাতীয় পোশাক 'দৌরা সুরুয়াল' বা 'গুন্যু-চলো'র মতো আমিও সেখানে চলাফেরার সময় শালীন ও স্থানীয় পরিবেশের সাথে সামঞ্জস্যপূর্ণ পোশাক পরব, যাতে তাদের মূল্যবোধে আঘাত না লাগে।\n• খাদ্য ও আতিথেয়তাকে সম্মান: নেপালিদের বিখ্যাত খাবার 'ঢেড়ো' বা 'থাকালি থালি'র প্রতি আগ্রহ দেখাব। তাদের পরিবেশিত খাবারের প্রশংসা করব এবং কোনো অভ্যাস যদি আমার কাছে নতুন বা অপরিচিত মনে হয়, তবুও তা নিয়ে কোনো নেতিবাচক মন্তব্য বা উপহাস করব না।\n• সামাজিক শিষ্টাচার: নেপালিদের সাথে কথা বলার সময় তাদের ভাষায় 'নমস্তে' বলে অভিবাদন জানাব। কারো অনুমতি ছাড়া ব্যক্তিগত বা ধর্মীয় অনুষ্ঠানের ছবি তুলব না। নেপালের বিভিন্ন উৎসব যেমন-বিজয়া দশমী, দশাইন বা তিহারের সময় স্থানীয়দের উৎসবে বাধা সৃষ্টি না করে বরং শ্রদ্ধার সাথে তা পর্যবেক্ষণ করব।\nপরিশেষে, প্রতিটি জাতির সংস্কৃতিই তার পরিচয়। নেপালিদের এই সহজ-সরল জীবনযাত্রা ও ঐতিহ্যকে সম্মান জানানোর মাধ্যমেই আমি একজন দায়িত্বশীল পর্যটক হিসেবে আমার দেশের ভাবমূর্তি উজ্জ্বল করতে পারব।"}]}},{"no":8,"title":"আঞ্চলিক ও আন্তর্জাতিক সংস্থা","q":{"mcq":[{"n":"১","q":"সার্কের প্রতিষ্ঠাকালীন সদস্য দেশ কয়টি ছিল?","a":"খ) ৭টি","o":["৬টি","৭টি","৮টি","৯টি"]},{"n":"২","q":"মুসলিম দেশগুলো নিজেদের মধ্যে সহযোগিতার জন্য নিচের কোন সংস্থাটি গড়ে তোলে?","a":"গ) ওআইসি","o":["সার্ক","জাতিসংঘ","ওআইসি","ওপেক"]},{"n":"৩","q":"বিশ্বশান্তি ও নিরাপত্তা প্রতিষ্ঠার জন্য কাজ করে কোন সংস্থা?","a":"খ) জাতিসংঘ","o":["সার্ক","জাতিসংঘ","ওআইসি","ওপেক"]}],"blank":[{"n":"১","q":"সার্কের সদস্য দেশগুলো একে অপরের সার্বভৌমত্বের প্রতি ______ হবে।","a":"শ্রদ্ধাশীল"},{"n":"২","q":"ওআইসির একটি কাজ হচ্ছে ______ নির্মূল করা।","a":"বর্ণবৈষম্য"},{"n":"৩","q":"বিশ্বের সকল দেশের মানুষই ______ আবিষ্কারের সুবিধা ভোগ করতে পারে।","a":"জনকল্যাণমূলক"}],"match":[{"n":"১","q":"সার্ক","a":"কাঠমান্ডু"},{"n":"২","q":"ওআইসি","a":"জেদ্দা"},{"n":"৩","q":"জাতিসংঘ","a":"নিউইয়র্ক"}],"short":[{"n":"১","q":"সার্ক গঠনের তিনটি উদ্দেশ্য লেখ।","a":"সার্ক গঠনের তিনটি প্রধান উদ্দেশ্য হলো সদস্য দেশগুলোর মধ্যে বন্ধুত্বপূর্ণ সম্পর্ক সৃষ্টি করা, পারস্পরিক সহযোগিতার মাধ্যমে অর্থনৈতিক উন্নয়ন ত্বরান্বিত করা এবং এ অঞ্চলের মানুষের জীবনযাত্রার মানোন্নয়ন করা।"},{"n":"২","q":"মুসলিম দেশগুলোর স্বার্থরক্ষায় ওআইসির তিনটি কাজ লেখ।","a":"মুসলিম দেশগুলোর স্বার্থরক্ষায় ওআইসি-র তিনটি প্রধান কাজ হলো সদস্য দেশগুলোর মধ্যে সামাজিক ও অর্থনৈতিক সহযোগিতা বৃদ্ধি করা, বিভিন্ন দেশে সংখ্যালঘু মুসলিম সম্প্রদায়ের অধিকার রক্ষা করা এবং মুসলমানদের মান-মর্যাদা ও জাতীয় অধিকার সংরক্ষণে শক্তি জোগানো।"}],"essay":[{"n":"১","q":"আমরা সকলেই কীভাবে বিশ্ব পরিবারের সদস্য?","a":"বর্তমান যুগে মানুষ যেমন এককভাবে চলতে পারে না, তেমনি বিশ্বের রাষ্ট্রগুলোও একে অপরের সহযোগিতা ছাড়া অচল। আমরা সকলেই যে একটি বিশাল বিশ্ব পরিবারের সদস্য, তা নিচের আলোচনা থেকে স্পষ্ট হয়:\n• পারস্পরিক নির্ভরশীলতা: বিশ্বের প্রতিটি দেশ শিক্ষা, স্বাস্থ্য, কৃষি, অর্থনীতি, পরিবেশ এবং প্রযুক্তির মতো মৌলিক ক্ষেত্রে একে অপরের ওপর গভীরভাবে নির্ভরশীল। কোনো দেশই সব দিক দিয়ে স্বয়ংসম্পূর্ণ নয়, তাই নিজেদের প্রয়োজন মেটাতে দেশগুলোকে একে অন্যের দ্বারস্থ হতে হয়।\n• যৌথ সমস্যার মোকাবিলা: বর্তমানে জলবায়ু পরিবর্তন বা বৈশ্বিক উষ্ণায়নের মতো সমস্যাগুলো কোনো নির্দিষ্ট দেশের সীমানায় সীমাবদ্ধ নয়। এক দেশের পরিবেশগত ক্ষতির প্রভাব অন্য দেশকেও ভোগ করতে হয়। এই সাধারণ বিপদগুলো আমাদের মনে করিয়ে দেয় যে আমরা সবাই একই পৃথিবীর বাসিন্দা এবং একে অপরের সাথে যুক্ত।\n• জ্ঞানের অংশীদারিত্ব: কোনো দেশের কল্যাণমূলক আবিষ্কার বা বৈজ্ঞানিক উদ্ভাবনের সুফল বিশ্বের সব দেশের মানুষই ভোগ করতে পারে। একইভাবে যোগাযোগ ও তথ্য-প্রযুক্তির উন্নয়নের ফলে তথ্য এখন সবার জন্য উন্মুক্ত, যা বিশ্বকে একটি 'গ্লোবাল ভিলেজ' বা বিশ্ব গ্রামে পরিণত করেছে।\n• সংহতি ও সহযোগিতা: সার্ক, ওআইসি এবং জাতিসংঘের মতো আঞ্চলিক ও আন্তর্জাতিক সংস্থাগুলোর অস্তিত্ব আমাদের এই ধারণাকে আরও দৃঢ় করে যে আমরা একটি বিশ্ব পরিবারের সদস্য। এই সংস্থাগুলো দেশগুলোর মধ্যে বন্ধুত্ব ও সম্প্রীতি বজায় রেখে বিশ্বশান্তি প্রতিষ্ঠায় কাজ করে।\nপরিশেষে, আমরা যখন নিজেদের দক্ষ বিশ্ব নাগরিক হিসেবে গড়ে তুলি, তখন আমাদের কাজের প্রভাব শুধু নিজের দেশেই নয়, বরং সারা বিশ্বে পড়ে। এই দায়িত্ববোধই আমাদের বিশ্ব পরিবারের অবিচ্ছেদ্য অংশ হিসেবে চিহ্নিত করে।"},{"n":"২","q":"আন্তর্জাতিক সংস্থাগুলো আমাদের জীবনমান উন্নয়নে কীভাবে ভূমিকা রাখতে পারে?","a":"আন্তর্জাতিক সংস্থাগুলো বিশ্বের দেশগুলোর মধ্যে সেতুবন্ধন হিসেবে কাজ করে এবং মানুষের জীবনযাত্রার মানোন্নয়নে নানামুখী ভূমিকা পালন করে:\n• শান্তি ও নিরাপত্তা নিশ্চিতকরণ: জাতিসংঘ বা ওআইসি-র মতো সংস্থাগুলো বিশ্বশান্তি ও নিরাপত্তা প্রতিষ্ঠায় কাজ করে। যুদ্ধ বা সংঘাতময় পরিস্থিতিতে এসব সংস্থা মধ্যস্থতা করে শান্তি ফিরিয়ে আনে, যা মানুষের স্বাভাবিক জীবনযাত্রার জন্য অপরিহার্য।\n• আর্থ-সামাজিক সহযোগিতা: এই সংস্থাগুলো সদস্য দেশগুলোর মধ্যে অর্থনৈতিক ও সামাজিক সহযোগিতার ক্ষেত্র তৈরি করে। বিশেষ করে সার্কের মতো সংস্থাগুলো একটি 'জরুরি তহবিল' গঠনের মাধ্যমে সদস্য দেশগুলোর আর্থিক সংকট মোকাবিলায় ও দারিদ্র‍্য বিমোচনে সহায়তা করে।\n• শিক্ষা ও স্বাস্থ্যসেবা: আন্তর্জাতিক সংস্থাগুলো বিশ্বব্যাপী শিক্ষা ও স্বাস্থ্যের মানোন্নয়নে কাজ করে। তারা সদস্য দেশগুলোকে আধুনিক প্রযুক্তি ও উন্নত চিকিৎসা সরঞ্জাম সরবরাহ করে এবং মহামারীর মতো দুর্যোগের সময় কারিগরি সহায়তা প্রদান করে জীবন রক্ষা করে।\n• প্রযুক্তির আদান-প্রদান: বর্তমান যুগে তথ্য ও যোগাযোগ প্রযুক্তি উন্নয়নের ক্ষেত্রে আন্তর্জাতিক সংস্থাগুলো গুরুত্বপূর্ণ ভূমিকা রাখে। দেশগুলোর মধ্যে বৈজ্ঞানিক গবেষণার ফল শেয়ার করা এবং নতুন প্রযুক্তি ব্যবহারে সহায়তা করার ফলে মানুষের কাজ সহজ ও গতিশীল হচ্ছে।\n• পরিবেশ ও শক্তি উন্নয়ন: জলবায়ু পরিবর্তনের ঝুঁকি মোকাবিলায় এই সংস্থাগুলো সৌরশক্তির মতো নবায়নযোগ্য জ্বালানি ব্যবহারে দেশগুলোকে উৎসাহিত করে এবং প্রয়োজনীয় আর্থিক ও কারিগরি সহায়তা প্রদান করে।\nসংক্ষেপে, আন্তর্জাতিক সংস্থাগুলো বিশ্বের দেশগুলোকে একটি একক প্ল্যাটফর্মে এনে বৈষম্য দূর করে এবং যৌথ প্রচেষ্টার মাধ্যমে মানুষের জীবনযাত্রাকে আরও উন্নত, নিরাপদ ও আধুনিক করে তোলে।"}]}},{"no":9,"title":"রাষ্ট্র এবং সমাজে আমাদের অধিকার ও কর্তব্য","q":{"mcq":[{"n":"১","q":"ভোট প্রদান করা নাগরিকের কোন ধরনের অধিকার?","a":"খ) রাজনৈতিক অধিকার","o":["সামাজিক অধিকার","রাজনৈতিক অধিকার","ব্যক্তিগত অধিকার","অর্থনৈতিক অধিকার"]},{"n":"২","q":"নিচের কোনটি বুলিংয়ের উদাহরণ?","a":"ক) ব্যঙ্গ করে ডাকা","o":["ব্যঙ্গ করে ডাকা","দলীয় কাজে বাধা দেওয়া","মতামত প্রকাশে বাধা দেওয়া","খেলায় অংশগ্রহণে বাধা দেওয়া"]}],"blank":[{"n":"১","q":"সামাজিক সমস্যা মানুষের স্বাভাবিক ______ ব্যাহত করে।","a":"জীবনযাপন"},{"n":"২","q":"স্টুডেন্টস কাউন্সিলের মাধ্যমে ______ প্রদান করার দক্ষতা অর্জন করা যায়।","a":"নেতৃত্ব"},{"n":"৩","q":"আমি স্বাধীনভাবে মত প্রকাশ করি- এটা আমার ______।","a":"অধিকার"}],"truefalse":[{"n":"১","q":"সমাজে সমান মর্যাদা পাওয়া একটি মানবাধিকার।","a":"সত্য"},{"n":"২","q":"১৮ বছর বয়সে রাষ্ট্রের সকল নাগরিক ভোটদানের যোগ্যতা অর্জন করে।","a":"সত্য"},{"n":"৩","q":"সামাজিক সমস্যা সমাজের অগ্রগতিকে ত্বরান্বিত করে।","a":"মিথ্যা"}],"short":[{"n":"১","q":"নাগরিক অধিকার বলতে কী বোঝ?","a":"রাষ্ট্র তার নাগরিকদের বিকাশের জন্য যেসব সুযোগ-সুবিধা প্রদান করে, তাকেই নাগরিক অধিকার বলে। যেমন-শিক্ষা গ্রহণ, ভোটদান এবং আইন মেনে চলার মাধ্যমে রাষ্ট্রের সুযোগ-সুবিধা ভোগ করা।"},{"n":"২","q":"মাদকাসক্তির তিনটি ক্ষতিকর প্রভাব লেখ।","a":"মাদকাসক্তির তিনটি ক্ষতিকর প্রভাব হলো:\n• এর ফলে মানুষের অপূরণীয় শারীরিক ও মানসিক ক্ষতি হয়।\n• মানুষ তার স্বাভাবিক কর্মক্ষমতা ও চিন্তাশক্তি হারিয়ে ফেলে।\n• এটি মানুষকে স্বাভাবিক জীবনযাপনে বাধাগ্রস্ত করে এবং সমাজ থেকে বিচ্ছিন্ন করে দেয়।"},{"n":"৩","q":"শিশুর উপর মোবাইল আসক্তির তিনটি ক্ষতিকর প্রভাব লেখ।","a":"শিশুর ওপর মোবাইল আসক্তির তিনটি ক্ষতিকর প্রভাব হলো:\n• শিশুদের পড়াশোনায় চরম অমনোযোগিতা তৈরি হয়।\n• তাদের মেজাজ খিটখিটে হয়ে যায় এবং আচরণে পরিবর্তন আসে।\n• মোবাইল আসক্তির ফলে শিশুদের খাবারের প্রতি অনীহা দেখা দেয়, যা স্বাস্থ্যের ক্ষতি করে।"}],"essay":[{"n":"১","q":"বাল্যবিবাহ প্রতিরোধের উপায়গুলো বর্ণনা করো।","a":"বাল্যবিবাহ একটি মারাত্মক সামাজিক ব্যাধি যা একটি মেয়ের শারীরিক ও মানসিক বিকাশকে বাধাগ্রস্ত করে। এটি প্রতিরোধে আমাদের ব্যক্তিগত ও সামাজিকভাবে সচেতন হওয়া প্রয়োজন। বাল্যবিবাহ প্রতিরোধের প্রধান উপায়গুলো নিচে বর্ণনা করা হলো:\n• পারিবারিক ও সামাজিক সচেতনতা: বাল্যবিবাহের কুফল সম্পর্কে পরিবার ও সমাজকে সচেতন করতে হবে। মেয়েদের পড়াশোনার গুরুত্ব এবং অল্প বয়সে বিয়ের শারীরিক ঝুঁকির কথা অভিভাবকদের বোঝাতে হবে।\n• প্রতিরোধ গড়ে তোলা: আমাদের আশেপাশে কোথাও বাল্যবিবাহের আয়োজন হতে দেখলে তা সরাসরি বাধা দিতে হবে বা প্রতিরোধ করতে হবে। স্থানীয়ভাবে উঠান বৈঠক বা সভা-সমাবেশ করে এর বিরুদ্ধে জনমত তৈরি করা জরুরি।\n• আইনি সহায়তা গ্রহণ: বাল্যবিবাহ একটি দ-নীয় অপরাধ। কোথাও বাল্যবিবাহ হতে দেখলে দ্রুত সরকারি হটলাইন নম্বর ১০৯৮ (শিশু সহায়তা) অথবা ১০৯ (নারী ও শিশু নির্যাতন প্রতিরোধ) নম্বরে ফোন করে সাহায্য নিতে হবে।\n• স্থানীয় প্রশাসনের ভূমিকা: বাল্যবিবাহের খবর পাওয়া মাত্রই স্থানীয় মেম্বার, চেয়ারম্যান বা নারী প্রতিনিধিদের জানাতে হবে। বিবাহ নিবন্ধক বা কাজীদের কঠোর নির্দেশ দিতে হবে যাতে তারা আইন অনুযায়ী বয়স নিশ্চিত না হয়ে বিয়ে না পড়ান।\n• প্রচারণা ও শিক্ষা: পোস্টার, ব্যানার, রেডিও এবং টেলিভিশনের মাধ্যমে বাল্যবিবাহের বিরুদ্ধে প্রচারণা চালাতে হবে। বিদ্যালয়গুলোতে শিক্ষকদের মাধ্যমে শিক্ষার্থীদের সচেতন করা এবং মেয়েদের ঝরে পড়া রোধে পদক্ষেপ নিতে হবে।"},{"n":"২","q":"মানবাধিকার রক্ষায় আমাদের করণীয়গুলো বর্ণনা করো।","a":"মানবাধিকার হলো মানুষের জন্মগত অধিকার যা তাকে মর্যাদার সাথে বেঁচে থাকতে সাহায্য করে। সমাজে মানবাধিকার নিশ্চিত করতে আমাদের কিছু গুরুত্বপূর্ণ দায়িত্ব ও কর্তব্য রয়েছে:\n• আইন ও নীতি মেনে চলা: মানবাধিকার রক্ষার জন্য রাষ্ট্রের প্রচলিত আইন ও নীতিমালাগুলো যথাযথভাবে মেনে চলা আমাদের প্রধান দায়িত্ব। অন্যের অধিকারে হস্তক্ষেপ না করা এবং মানবাধিকারের প্রতি শ্রদ্ধাশীল থাকা প্রয়োজন।\n• জনসচেতনতা তৈরি: মানবাধিকার কী এবং কেন এটি গুরুত্বপূর্ণ, সে বিষয়ে সাধারণ মানুষের মধ্যে সচেতনতা বৃদ্ধি করতে হবে। পোস্টার বা স্লোগানের মাধ্যমে মানবাধিকারের বার্তা সবার কাছে পৌঁছে দিতে হবে।\n• বৈষম্য দূর করা: অধিকার পাওয়ার ক্ষেত্রে জাতি, ধর্ম, বর্ণ বা নারী-পুরুষের মধ্যে কোনো ধরনের ভেদাভেদ করা যাবে না। সমাজের দুর্বল ও সুবিধাবঞ্চিত শ্রেণির অধিকার রক্ষায় বিশেষ নজর দিতে হবে।\n• আইনি সহায়তা ও প্রতিবাদ: মানবাধিকার লঙ্ঘনের কোনো ঘটনা (যেমন: শিশুশ্রম, নির্যাতন বা সম্পত্তি থেকে বঞ্চিত করা) দেখলে চুপ না থেকে তার প্রতিবাদ করতে হবে। ভুক্তভোগীদের ন্যায়বিচার পেতে আইনি সহায়তা প্রদানে এগিয়ে আসতে হবে।\n• মত প্রকাশের স্বাধীনতা নিশ্চিত করা: অন্যের ক্ষতি না করে গঠনমূলকভাবে নিজের মত প্রকাশের সুযোগ দিতে হবে। সেই সাথে সংবাদমাধ্যম ও সামাজিক মাধ্যমে মানবাধিকারের সুফলগুলো তুলে ধরতে হবে।\nএই পদক্ষেপগুলো গ্রহণের মাধ্যমে আমরা একটি সুন্দর, ন্যায়ভিত্তিক এবং বৈষম্যহীন সমাজ গড়ে তুলতে পারি যেখানে প্রত্যেকের মানবাধিকার সুরক্ষিত থাকবে।"}]}},{"no":10,"title":"নৈতিক ও সামাজিক আচরণ","q":{"mcq":[{"n":"১","q":"গণতান্ত্রিক আচরণের পূর্বশর্ত কোনটি?","a":"খ) অন্যের মতামতকে গুরুত্ব দেয়া","o":["নিজের মতামতকে প্রাধান্য দেওয়া","অন্যের মতামতকে গুরুত্ব দেয়া","যার মত পছন্দ হয় তার কথা শোনা","নিজের মতো সিদ্ধান্ত নেয়া"]},{"n":"২","q":"পরমতসহিষ্ণুতা আমাদের কী শেখায়?","a":"ক) সহনশীলতা","o":["সহনশীলতা","নৈতিকতা","নান্দনিকতা","সৃজনশীলতা"]}],"blank":[{"n":"১","q":"প্রত্যেকের বিশ্বাসকে সম্মান করতে প্রয়োজন ______।","a":"পরমতসহিষ্ণুতা"},{"n":"২","q":"সকলেরই অন্যের মতামতকে ______ করা উচিত।","a":"সম্মান"}],"short":[{"n":"১","q":"পরমতসহিষ্ণুতা কী?","a":"পরমতসহিষ্ণুতা হলো নিজের মত প্রকাশের পাশাপাশি অন্যের মতামতের প্রতি শ্রদ্ধা প্রদর্শন করা এবং অন্যের ভিন্ন মতকে ধৈর্যের সাথে গ্রহণ করা। এটি সমাজে শান্তি-শৃঙ্খলা বজায় রাখতে এবং সবার সাথে মিলেমিশে বাস করতে সাহায্য করে।"},{"n":"২","q":"বিদ্যালয়ে গণতান্ত্রিক চর্চার তিনটি ক্ষেত্র লেখ।","a":"বিদ্যালয়ে গণতান্ত্রিক চর্চার তিনটি ক্ষেত্র হলো:\n• শ্রেণিনেতা বা ক্যাপ্টেন নির্বাচন করা।\n• শিক্ষাসফরে যাওয়ার স্থান নির্ধারণের জন্য সবার মতামত নেওয়া।\n• শ্রেণিকক্ষ কীভাবে সাজানো বা পরিষ্কার রাখা হবে তা সকলে মিলে সিদ্ধান্ত নেওয়া।"}],"essay":[{"n":"১","q":"শ্রেণিকক্ষে সহপাঠীদের সাথে পরমতসহিষ্ণুতা প্রদর্শনের উপায়","a":"শ্রেণিকক্ষ হলো আমাদের শেখার প্রাথমিক স্থান, যেখানে বিভিন্ন মেধা ও মননের সহপাঠীরা একত্রে থাকে। সহপাঠীদের সাথে পরমতসহিষ্ণুতা প্রদর্শনের জন্য আমি নিম্নলিখিত পদক্ষেপগুলো গ্রহণ করব:\n• মতামতকে শ্রদ্ধা জানানো: কোনো বিষয় নিয়ে আলোচনা করার সময় আমার সহপাঠী যদি আমার থেকে ভিন্ন মত পোষণ করে, তবে আমি তার ওপর রাগ করব না। বরং ধৈর্য সহকারে তার কথা শুনব এবং তার মতের প্রতি সম্মান প্রদর্শন করব।\n• মত প্রকাশের সুযোগ দেওয়া: প্রতিটি মানুষেরই নিজস্ব মতামত রয়েছে। তাই দলগত কোনো কাজে আমি একাই কথা না বলে অন্য সহপাঠীদেরও তাদের মনের ভাব বা পরিকল্পনা প্রকাশের সমান সুযোগ করে দেব।\n• তর্ক এড়িয়ে চলা: অনেক সময় তুচ্ছ বিষয় নিয়ে সহপাঠীদের মধ্যে কথা-কাটাকাটি শুরু হয়, যেমনটি আমরা নববর্ষের পোশাক নিয়ে বন্ধুদের মধ্যে হতে দেখেছি। এমন পরিস্থিতিতে আমি তপু ও মিলির মতো শান্ত থেকে সকলকে বোঝাব যে প্রত্যেকের পছন্দ আলাদা হতে পারে এবং সবার পছন্দই সুন্দর।\n• সহনশীল হওয়া: পরমতসহিষ্ণুতা আমাদের সহনশীলতা শেখায়। তাই শ্রেণিকক্ষে কোনো সিদ্ধান্ত নেওয়ার সময় যদি আমার প্রস্তাব গৃহীত না হয়, তবে আমি মন খারাপ না করে অধিকাংশের মতকে মেনে নেব। এতে শ্রেণিকক্ষে সম্প্রীতি ও শান্তি-শৃঙ্খলা বজায় থাকবে।"},{"n":"২","q":"বিদ্যালয়ে শ্রেণিনেতা নির্বাচনের ক্ষেত্রে গণতান্ত্রিক চর্চা","a":"বিদ্যালয়ে শ্রেণিনেতা বা ক্যাপ্টেন নির্বাচন একটি গুরুত্বপূর্ণ প্রক্রিয়া যেখানে গণতান্ত্রিক আচরণের পূর্ণ প্রতিফলন ঘটানো সম্ভব। এই ক্ষেত্রে আমি যেভাবে গণতান্ত্রিক চর্চা করব:\n• সবার অংশগ্রহণ নিশ্চিত করা: শ্রেণিনেতা নির্বাচনের ক্ষেত্রে আমি দাবি করব যেন প্রতিটি শিক্ষার্থীর মতামত নেওয়া হয়। কারো একক সিদ্ধান্তে বা শিক্ষকের সরাসরি পছন্দে নেতা নির্বাচন না করে সবার অংশগ্রহণ নিশ্চিত করার পক্ষে থাকব।\n• ভোট প্রদান প্রক্রিয়া: সলিমপুর সরকারি প্রাথমিক বিদ্যালয়ের শিক্ষা সফরের স্থান নির্বাচনের মতো এখানেও আমি গোপন ব্যালট বা চিরকুটে নাম লিখে ভোট দেওয়ার প্রস্তাব দেব। এতে প্রত্যেক শিক্ষার্থী নির্দ্বিধায় তার পছন্দের প্রার্থীর নাম লিখতে পারবে।\n• অধিকাংশের মতামতকে প্রাধান্য দেওয়া: ভোট গণনা শেষে দেখা যাবে কোনো একজন প্রার্থী সবচেয়ে বেশি ভোট পেয়েছেন। গণতান্ত্রিক নিয়ম অনুযায়ী, আমি সেই অধিকাংশের মতামতকে শ্রদ্ধাভরে গ্রহণ করব।\n• ফলাফল মেনে নেওয়া: যদি আমার পছন্দের প্রার্থী নির্বাচিত না-ও হয়, তবুও আমি অধিকাংশের দ্বারা নির্বাচিত নেতার প্রতি শ্রদ্ধাশীল থাকব। কারণ অধিকাংশের মতামতের ভিত্তিতে সিদ্ধান্ত নেওয়াই হলো প্রকৃত গণতান্ত্রিক আচরণ, যা সবাইকে খুশি রাখে এবং বিশৃঙ্খলা রোধ করে।"}]}},{"no":11,"title":"বাংলাদেশের যোগাযোগ মানচিত্র","q":{"mcq":[{"n":"১","q":"সড়ক পথে যোগাযোগের বাহন কোনটি?","a":"গ) বাস","o":["লঞ্চ","ট্রেন","বাস","উড়োজাহাজ"]},{"n":"২","q":"কোন যোগাযোগ ব্যবস্থায় পণ্য পরিবহণ ব্যয় কম?","a":"গ) নদীপথ","o":["সড়কপথ","রেলপথ","নদীপথ","আকাশপথ"]},{"n":"৩","q":"তুমি ঢাকা থেকে ময়মনসিংহে সহজে কোন পথে যাবে?","a":"খ) সড়ক ও রেল","o":["সড়ক ও নদী","সড়ক ও রেল","রেল ও নদী","নদী ও আকাশ"]}],"truefalse":[{"n":"১","q":"বাংলাদেশে যোগাযোগ ব্যবস্থায় সড়কপথ সবচেয়ে বেশি ব্যবহৃত হয়।","a":"সত্য"},{"n":"২","q":"পায়রা বাংলাদেশের অন্যতম নদীবন্দর।","a":"সত্য"},{"n":"৩","q":"জিপিএস-এর মাধ্যমে নিখুঁতভাবে কোনো কিছুর অবস্থান নির্ণয় করা যায়।","a":"সত্য"}],"short":[{"n":"১","q":"বাংলাদেশে সাধারণত কী কী ধরনের যোগাযোগ ব্যবস্থা আছে?","a":"বাংলাদেশে সাধারণত সড়কপথ, নৌপথ, রেলপথ ও আকাশপথ-এই চার ধরনের যোগাযোগ ব্যবস্থা রয়েছে। এর মধ্যে পণ্য ও যাত্রী পরিবহনে সড়কপথ সবচেয়ে বেশি ব্যবহৃত হয় এবং সাশ্রয়ী যাতায়াতের জন্য নৌপথ ও রেলপথ জনপ্রিয়।"},{"n":"২","q":"বাংলাদেশের অভ্যন্তরীণ ও আন্তর্জাতিক বিমানবন্দরের তিনটি করে নাম লেখ।","a":"তিনটি আন্তর্জাতিক বিমানবন্দর হলো হযরত শাহজালাল আন্তর্জাতিক বিমানবন্দর (ঢাকা), শাহ আমানত আন্তর্জাতিক বিমানবন্দর (চট্টগ্রাম) এবং ওসমানী আন্তর্জাতিক বিমানবন্দর (সিলেট)। তিনটি অভ্যন্তরীণ বিমানবন্দর হলো যশোর, রাজশাহী ও সৈয়দপুর বিমানবন্দর।"}],"essay":[{"n":"১","q":"বাংলাদেশের বিভিন্ন যোগাযোগ ব্যবস্থার গুরুত্ব বর্ণনা করো","a":"একটি দেশের অর্থনৈতিক ও সামাজিক উন্নয়নের অন্যতম প্রধান ভিত্তি হলো তার উন্নত যোগাযোগ ব্যবস্থা। বাংলাদেশের প্রেক্ষাপটে চারটি প্রধান যোগাযোগ ব্যবস্থার গুরুত্ব অপরিসীম:\n• সড়কপথ: এটি বাংলাদেশের সবচেয়ে বিস্তৃত ও বেশি ব্যবহৃত পথ। দেশের জাতীয়, আঞ্চলিক ও জেলা সড়কগুলো গ্রাম ও শহরের মধ্যে সেতুবন্ধন তৈরি করে পণ্য ও যাত্রী পরিবহনে মুখ্য ভূমিকা পালন করে। মেট্রোরেল ও উড়াল সড়কের মতো আধুনিক সংযোজনগুলো বর্তমানে যানজট নিরসনে ও দ্রুত যাতায়াতে বৈপ্লবিক পরিবর্তন এনেছে।\n• রেলপথ: বাংলাদেশের সাধারণ মানুষের কাছে রেলপথ অত্যন্ত জনপ্রিয় ও নিরাপদ মাধ্যম। মিটারগেজ, ব্রডগেজ ও ডুয়েলগেজ লাইনের মাধ্যমে এটি দেশের এক প্রান্ত থেকে অন্য প্রান্তে স্বল্প খরচে ভারী মালামাল ও যাত্রী পরিবহনে সহায়তা করে।\n• নৌপথ: নদীমাতৃক বাংলাদেশে পণ্য পরিবহনের ক্ষেত্রে নৌপথ সবচেয়ে সাশ্রয়ী মাধ্যম। অভ্যন্তরীণ নদীবন্দর (যেমন: ঢাকা, চাঁদপুর) এবং সমুদ্রবন্দরগুলো (যেমন: চট্টগ্রাম, মোংলা ও পায়রা) বিদেশের সাথে আমদানি-রপ্তানি বাণিজ্যের মূল চালিকাশক্তি হিসেবে কাজ করে।\n• আকাশপথ: দ্রুততম যাতায়াতের জন্য বর্তমানে আকাশপথের গুরুত্ব বাড়ছে। আন্তর্জাতিক তিনটি বিমানবন্দরের মাধ্যমে এটি বৈশ্বিক যোগাযোগ এবং জরুরি অভ্যন্তরীণ প্রয়োজনে (যেমন: যশোর বা সৈয়দপুর যাতায়াত) অপরিহার্য ভূমিকা রাখে।"},{"n":"২","q":"জিপিএস (GPS)-এর ব্যবহার লেখ","a":"জিপিএস বা Global Positioning System আধুনিক যোগাযোগ প্রযুক্তির এক বিস্ময়কর উদ্ভাবন, যার ব্যবহার বর্তমানে বহুমুখী। এর প্রধান ব্যবহারসমূহ নিচে তুলে ধরা হলো:\n• অবস্থান ও দিকনির্ণয়: জিপিএস-এর মাধ্যমে পৃথিবীর যেকোনো প্রান্তের নিখুঁত অবস্থান নির্ণয় করা যায়। এটি ব্যবহার করে অচেনা পথে নির্দিষ্ট গন্তব্য নির্বাচন করলে 'Google Map'-এর মতো অ্যাপগুলো তীরের সাহায্যে নির্ভুল পথ নির্দেশ করে।\n• সেবা প্রদানকারী প্রতিষ্ঠানের সন্ধান: জিপিএস ডিভাইসের ডিসপ্লেতে রাস্তার পাশাপাশি নিকটস্থ পেট্রোল পাম্প, পুলিশ স্টেশন, হোটেল, রেস্টুরেন্ট এবং পর্যটন কেন্দ্রের মতো জরুরি স্থাপনার অবস্থান প্রদর্শিত হয়।\n• সময় ও ট্র‍্যাফিক ব্যবস্থাপনা: হেঁটে, বাসে বা মোটরসাইকেলে গন্তব্যে পৌঁছাতে সম্ভাব্য কত সময় লাগবে, তা জিপিএস-এর মাধ্যমে আগেভাগেই জানা সম্ভব। এছাড়া বড় বড় শহরে ট্র‍্যাফিক জ্যাম পর্যবেক্ষণ ও নিয়ন্ত্রণে এই প্রযুক্তি ব্যবহৃত হয়।\n• পরিবহণ নিয়ন্ত্রণ: গাড়ি, জাহাজ এবং প্লেনের অবস্থান ও গতিবিধি নির্ভুলভাবে শনাক্ত করতে জিপিএস সিস্টেম অপরিহার্য। বর্তমান যুগে মোবাইল ও ল্যাপটপে বিভিন্ন অ্যাপের মাধ্যমে এই প্রযুক্তি সাধারণ মানুষের যাতায়াতকে অনেক সহজ করে দিয়েছে।"}]}},{"no":12,"title":"বাংলাদেশের বনভূমি ও প্রাকৃতিক পর্যটন স্থান","q":{"mcq":[{"n":"১","q":"চিরসবুজ বনের প্রধান বৈশিষ্ট্য কোনটি?","a":"খ) সব সময় গাছে পাতা থাকে","o":["পাতা সবুজ থাকে","সব সময় গাছে পাতা থাকে","শীতকালে পাতা ঝরে যায়","সব সময় পাতা ঝরে যায়"]},{"n":"২","q":"শ্বাসমূল ও ঠেসমূল জন্মায় কোন বনে?","a":"ক) সুন্দরবনে","o":["সুন্দরবনে","জলাবনে","চিরসবুজ বনে","পাতাঝরা বনে"]},{"n":"৩","q":"মিঠা পানির জলাবন দেখতে তুমি কোথায় যাবে?","a":"ক) সিলেট","o":["সিলেট","টাঙ্গাইল","খুলনা","রাঙ্গামাটি"]},{"n":"৪","q":"একই স্থান থেকে সূর্যোদয় ও সূর্যাস্ত দেখতে চাও, কোথায় যাবে?","a":"ক) কুয়াকাটা","o":["কুয়াকাটা","ময়নামতি","পতেঙ্গা","জাফলং"]}],"blank":[{"n":"১","q":"বনভূমি ______ রক্ষায় গুরুত্বপূর্ণ ভূমিকা রাখে।","a":"জীববৈচিত্র‍্য"},{"n":"২","q":"গাছপালা মাটির ______ রোধ করে।","a":"ক্ষয়"},{"n":"৩","q":"পর্যটনের উন্নয়নের ফলে দেশের ______ উন্নয়ন হয়।","a":"অর্থনৈতিক"},{"n":"৪","q":"পর্যটন শিল্পের প্রসার দেশে বহু লোকের ______ সৃষ্টি করে।","a":"কর্মসংস্থান"}],"short":[{"n":"১","q":"ম্যানগ্রোভ বনের বৈশিষ্ট্য কী?","a":"ম্যানগ্রোভ বনের প্রধান বৈশিষ্ট্য হলো এটি নির্দিষ্ট সময় পর পর জোয়ারের পানিতে প্লাবিত হয়। এই বনের উদ্ভিদের শ্বাসমূল, ঠেসমূল এবং জরায়ুজ অঙ্কুরোদগম দেখা যায় যা একে অনন্য করে তুলেছে।"},{"n":"২","q":"ক্রান্তীয় চিরসবুজ বন ও পাতাঝরা বনের মধ্যে পার্থক্য কী?","a":"ক্রান্তীয় চিরসবুজ বনের গাছগুলোর পাতা সারা বছর থাকে এবং বনটি সবসময় সবুজ দেখায়। অন্যদিকে, পাতাঝরা বনের (শালবন) গাছগুলোর পাতা শীতকালে সম্পূর্ণ ঝরে যায়।"},{"n":"৩","q":"তিনটি প্রাকৃতিক পর্যটন স্থানের নাম লেখ।","a":"বাংলাদেশের তিনটি উল্লেখযোগ্য প্রাকৃতিক পর্যটন স্থান হলো:\n• বিশ্বের দীর্ঘতম বালুময় সমুদ্র সৈকত কক্সবাজার।\n• সিলেটের জাফলং, যা চা বাগান ও পিয়াইন নদীর সৌন্দর্যের জন্য পরিচিত।\n• পৃথিবীর বৃহত্তম ম্যানগ্রোভ বন সুন্দরবন।"},{"n":"৪","q":"প্রাকৃতিক পর্যটন স্থানের তিনটি গুরুত্ব লেখ।","a":"প্রাকৃতিক পর্যটন স্থানের তিনটি গুরুত্ব হলো:\n• এটি রাজস্ব আয় ও বৈদেশিক মুদ্রা অর্জনের একটি অত্যন্ত কার্যকর খাত।\n• পর্যটন শিল্পের বিকাশের ফলে দেশে বিপুল সংখ্যক মানুষের কর্মসংস্থান সৃষ্টি হয়।\n• এই স্থানগুলো পরিবেশের ভারসাম্য রক্ষা করে এবং মানুষের মানসিক প্রশান্তির উৎস হিসেবে কাজ করে।"}],"essay":[{"n":"১","q":"পরিবেশের ভারসাম্য রক্ষায় বনভূমির ভূমিকা ব্যাখা করো।","a":"মানব জীবনে এবং পরিবেশের ভারসাম্য রক্ষায় বনভূমির ভূমিকা অপরিসীম। একটি দেশের মোট ভূখ-ের অন্তত ২৫ শতাংশ বনভূমি থাকা প্রয়োজন, যদিও বাংলাদেশে বর্তমানে এর পরিমাণ প্রায় ১৭ শতাংশ। বনভূমির গুরুত্ব নিচে ব্যাখ্যা করা হলো:\n• প্রাকৃতিক দুর্যোগ মোকাবিলা: সুন্দরবন ও উপকূলীয় বনভূমি ঝড় ও জলোচ্ছ্বাসের মতো ভয়াবহ প্রাকৃতিক দুর্যোগ থেকে দেশকে রক্ষা করতে ঢাল হিসেবে কাজ করে। সমুদ্র তীরবর্তী জেলাগুলোতে গড়ে তোলা 'সবুজ বেষ্টনী' জলোচ্ছ্বাসের গতিবেগ কমিয়ে দেয়।\n• জীববৈচিত্র‍্য সংরক্ষণ: ঘন ও গভীর বনভূমি বিভিন্ন পশুপাখি ও কীটপতঙ্গের নিরাপদ আবাসস্থল। জীববৈচিত্র‍্য রক্ষায় এবং প্রাণীদের নির্ভয়ে বিচরণ নিশ্চিত করতে বনভূমির কোনো বিকল্প নেই।\n• জলবায়ু ও মৃত্তিকা সুরক্ষা: বনভূমি পরিবেশের তাপমাত্রা নিয়ন্ত্রণ করে এবং এলাকাকে মরুভূমিতে পরিণত হওয়া থেকে রক্ষা করে। গাছের শিকড় মাটির গভীরে গিয়ে মাটির ক্ষয়রোধ করে এবং পরিবেশকে নির্মল রাখে।\n• সম্পদের উৎস: বন থেকে আমরা ঘরবাড়ি ও আসবাবপত্র তৈরির কাঠ, জ্বালানি, ফল, মধু এবং মূল্যবান ঔষধি উপকরণ পাই।"},{"n":"২","q":"বাংলাদেশের প্রাকৃতিক পর্যটন স্থান সংরক্ষণে তুমি কীভাবে ভূমিকা রাখবে তা বর্ণনা করো।","a":"বাংলাদেশের প্রাকৃতিক পর্যটন স্থানগুলো যেমন আমাদের গর্ব, তেমনি এগুলো আমাদের অর্থনীতির বড় উৎস। তবে বর্তমানে অপরিকল্পিত স্থাপনা নির্মাণ এবং দূষণের কারণে এই সৌন্দর্য হুমকির মুখে। একজন সচেতন নাগরিক হিসেবে আমি যেভাবে ভূমিকা রাখতে পারি:\n• দূষণ রোধে সচেতনতা: পর্যটন স্থানে ভ্রমণের সময় আমি নিজে যেখানে-সেখানে ময়লা-আবর্জনা ফেলব না এবং অন্যদেরও এটি করতে উৎসাহিত করব। বিশেষ করে প্লাস্টিক বর্জ্য যাতে পর্যটন কেন্দ্রের ক্ষতি না করে সেদিকে খেয়াল রাখব।\n• প্রকৃতি ও সম্পদ রক্ষা: বনের গাছপালা কাটা বা বন্যপ্রাণীর ক্ষতি করা থেকে বিরত থাকব। পর্যটন কেন্দ্রের প্রাকৃতিক পরিবেশ ও জীববৈচিত্র‍্য যাতে অক্ষুণ্ন থাকে, সে বিষয়ে জনসচেতনতা সৃষ্টি করব।\n• স্থাপনা নির্মাণে প্রতিবাদ: প্রাকৃতিক সৌন্দর্য নষ্ট করে এমন কোনো অপরিকল্পিত বা অবৈধ স্থাপনা নির্মাণের বিরুদ্ধে সোচ্চার হব।\n• প্রচারের মাধ্যমে উন্নয়ন: আমাদের পর্যটন স্থানগুলোর সৌন্দর্য ও সংরক্ষণের গুরুত্ব সামাজিক যোগাযোগমাধ্যম বা আলোচনার মাধ্যমে তুলে ধরব যাতে দেশি-বিদেশি পর্যটকদের আকর্ষণ বৃদ্ধি পায়।\n• সমন্বিত প্রচেষ্টায় অংশগ্রহণ: সরকারি ও বেসরকারি উদ্যোগের সাথে একাত্ম হয়ে বনায়ন এবং পর্যটন কেন্দ্রের সঠিক রক্ষণাবেক্ষণে সাধ্যমতো সহায়তা করব।\nবনভূমি ও প্রাকৃতিক পর্যটন স্থান রক্ষা করা আমাদের নৈতিক দায়িত্ব, কারণ এর সাথেই জড়িয়ে আছে আমাদের দেশের ভবিষ্যৎ অর্থনৈতিক ও পরিবেশগত সমৃদ্ধি।"}]}},{"no":13,"title":"বাংলাদেশের প্রাকৃতিক সম্পদ","q":{"mcq":[{"n":"১","q":"রান্নার কাজে জ্বালানি হিসাবে ব্যবহৃত গ্যাস কোন ধরনের সম্পদ?","a":"খ) খনিজ সম্পদ","o":["বনজ সম্পদ","খনিজ সম্পদ","নবায়নযোগ্য সম্পদ","সমুদ্র সম্পদ"]},{"n":"২","q":"কোন গুচ্ছটির সব কয়টি বনজ সম্পদ?","a":"গ) মোম, মধু ও সুন্দরী","o":["মধু, মোম ও তামা","মোম, তামা ও লৌহ","মোম, মধু ও সুন্দরী","মধু, কয়লা ও ফলমূল"]},{"n":"৩","q":"সমুদ্র সম্পদ ব্যবহারের সর্বোত্তম উপায় হচ্ছে কোনটি?","a":"ক) সঠিক উপায়ে সম্পদ আহরণ","o":["সঠিক উপায়ে সম্পদ আহরণ","জাহাজ চলাচল সীমিত করা","মাছ আহরণ সীমিত করা","সামুদ্রিক মাছের ব্যবহার হ্রাস করা"]}],"blank":[{"n":"১","q":"গ্যাস বাংলাদেশের প্রধান ______ সম্পদ।","a":"খনিজ"},{"n":"২","q":"আসবাবপত্র তৈরিতে ব্যবহৃত কাঠ ______ সম্পদের অন্তর্ভুক্ত।","a":"বনজ"},{"n":"৩","q":"কম খরচে বিদ্যুৎ উৎপাদনে ______ ব্যবহার হয়।","a":"কয়লা"}],"truefalse":[{"n":"১","q":"নদ-নদী সমুদ্র সম্পদের অন্তর্ভুক্ত।","a":"সত্য"},{"n":"২","q":"বাংলাদেশের খনিজ সম্পদের মধ্যে কয়লা ও প্রাকৃতিক গ্যাস উল্লেখযোগ্য।","a":"সত্য"},{"n":"৩","q":"লবণ ও মাছ বাংলাদেশের গুরুত্বপূর্ণ সামুদ্রিক সম্পদ।","a":"সত্য"}],"short":[{"n":"১","q":"প্রাকৃতিক গ্যাস কী কী কাজে ব্যবহার হয়?","a":"প্রাকৃতিক গ্যাস প্রধানত বিদ্যুৎ উৎপাদনে এবং শিল্প-কারখানায় জ্বালানি হিসেবে ব্যবহৃত হয়। এছাড়া রান্নার কাজে এবং সার তৈরির অপরিহার্য কাঁচামাল হিসেবেও এর ব্যাপক ব্যবহার রয়েছে।"},{"n":"২","q":"বাংলাদেশের প্রধান প্রধান গ্যাসক্ষেত্র কোথায় অবস্থিত?","a":"বাংলাদেশের প্রধান গ্যাসক্ষেত্রগুলো সিলেট, সুনামগঞ্জ, হবিগঞ্জ, ব্রাহ্মণবাড়িয়া এবং কুমিল্লা জেলায় অবস্থিত। এছাড়াও ভোলা, নরসিংদী ও গাজীপুর জেলাতেও গুরুত্বপূর্ণ গ্যাসক্ষেত্র রয়েছে।"},{"n":"৩","q":"বনজ সম্পদের মধ্যে বন্যপ্রাণী কেন গুরুত্বপূর্ণ?","a":"বন্যপ্রাণী বনের বাস্তুসংস্থান বা প্রকৃতির ভারসাম্য রক্ষায় অত্যন্ত গুরুত্বপূর্ণ ভূমিকা পালন করে। বন্যপ্রাণীর উপস্থিতি বনের জীববৈচিত্র‍্য টিকিয়ে রাখে এবং প্রাকৃতিক পরিবেশের স্থায়িত্ব নিশ্চিত করে।"},{"n":"৪","q":"নদীর পানি কী কী কাজে ব্যবহৃত হয়?","a":"নদীর পানি কৃষিকাজে সেচ দিতে এবং গৃহস্থালি ও শিল্পের বিভিন্ন প্রয়োজনে ব্যবহৃত হয়। এছাড়া মাছের আবাসস্থল হিসেবে এবং পণ্য পরিবহনের সস্তা মাধ্যম হিসেবেও নদীর পানির গুরুত্ব অপরিসীম।"}],"essay":[{"n":"১","q":"বনজ সম্পদের গুরুত্ব লেখ।","a":"বাংলাদেশের অর্থনীতি এবং পরিবেশের ভারসাম্য রক্ষায় বনজ সম্পদের গুরুত্ব অপরিসীম। আমাদের দেশের মোট ভূখ-ের একটি উল্লেখযোগ্য অংশ জুড়ে রয়েছে বিভিন্ন ধরনের বনাঞ্চল, যা আমাদের জীবনধারণের জন্য প্রয়োজনীয় বহু উপকরণের উৎস। বনজ সম্পদের গুরুত্ব নিচে তুলে ধরা হলো।\nপ্রথমত, বনভূমি আমাদের বেঁচে থাকার প্রধান উপাদান অক্সিজেন সরবরাহ করে এবং বায়ুম-ল থেকে ক্ষতিকর কার্বন ডাই-অক্সাইড শোষণ করে পরিবেশের ভারসাম্য বজায় রাখে। দ্বিতীয়ত, অর্থনৈতিক ক্ষেত্রে বনের অবদান অনস্বীকার্য। বনের সেগুন, মেহগনি, শাল ও সুন্দরীর মতো গাছ থেকে আমরা মূল্যবান কাঠ পাই, যা ঘরবাড়ি নির্মাণ, আসবাবপত্র তৈরি এবং নৌযান তৈরিতে ব্যবহৃত হয়। এছাড়া কাগজ শিল্পের প্রধান কাঁচামাল বাঁশ ও কাঠ বন থেকেই সংগৃহীত হয়।\nতৃতীয়ত, বনজ সম্পদ থেকে আমরা মধু, মোম, ফলমূল এবং বিভিন্ন ভেষজ ঔষধের কাঁচামাল পাই যা গ্রামীণ অর্থনীতিতে অবদান রাখে। চতুর্থত, বনভূমি বিভিন্ন বন্যপ্রাণীর নিরাপদ আবাসস্থল হিসেবে কাজ করে যা জীববৈচিত্র‍্য রক্ষায় অপরিহার্য। সবশেষে, বাংলাদেশের উপকূলীয় অঞ্চলের বনভূমি যেমন সুন্দরবন প্রাকৃতিক দুর্যোগ ও জলোচ্ছ্বাস থেকে উপকূলীয় এলাকাকে ঢাল হিসেবে রক্ষা করে। সুতরাং, পরিবেশ এবং অর্থনৈতিক সমৃদ্ধি উভয় দিক থেকেই বনজ সম্পদ আমাদের জাতীয় সম্পদ।"},{"n":"২","q":"প্রাকৃতিক সম্পদ সংরক্ষণের উপায় লেখ।","a":"প্রাকৃতিক সম্পদ সীমিত, তাই এর সঠিক ব্যবহার এবং সংরক্ষণ আমাদের অস্তিত্বের জন্য জরুরি। বিশেষ করে অনবায়নযোগ্য সম্পদ যেমন- গ্যাস ও কয়লা একবার শেষ হয়ে গেলে তা আর সহজে পাওয়া যাবে না। প্রাকৃতিক সম্পদ সংরক্ষণের প্রধান উপায়গুলো নিচে আলোচনা করা হলো।\n• পরিকল্পিত ও সাশ্রয়ী ব্যবহার: প্রাকৃতিক সম্পদের অপচয় রোধ করা সম্পদ সংরক্ষণের প্রথম ধাপ। রান্নার কাজ শেষে গ্যাসের চুলা নিভিয়ে রাখা এবং অপ্রয়োজনে লাইট-ফ্যান বন্ধ রাখার মাধ্যমে আমরা জ্বালানি ও বিদ্যুৎ সাশ্রয় করতে পারি। সম্পদের পরিকল্পিত আহরণ নিশ্চিত করতে হবে যেন তা বর্তমান ও ভবিষ্যৎ উভয় প্রজন্মের চাহিদা মেটাতে পারে।\n• বিকল্প শক্তির ব্যবহার: অনবায়নযোগ্য খনিজ সম্পদের ওপর চাপ কমাতে আমাদের নবায়নযোগ্য শক্তি যেমন- সৌরশক্তি, বায়ুশক্তি এবং জলবিদ্যুতের ব্যবহার বাড়াতে হবে। এটি দীর্ঘমেয়াদে পরিবেশ রক্ষা ও সম্পদ সংরক্ষণে সহায়তা করবে।\n• বনায়ন ও দূষণ নিয়ন্ত্রণ: বনজ সম্পদ বৃদ্ধিতে বাড়ির আঙিনায় ও পতিত জমিতে অধিক হারে বৃক্ষরোপণ করতে হবে। এছাড়া শিল্প-কারখানার বর্জ্য যাতে নদী বা সমুদ্রের পানিকে দূষিত না করে, সে বিষয়ে সতর্ক থাকতে হবে। পানি ও বায়ু দূষণ রোধ করা প্রাকৃতিক সম্পদ সংরক্ষণের একটি বড় অংশ।\n• জনসচেতনতা সৃষ্টি: সম্পদ সংরক্ষণের গুরুত্ব সম্পর্কে জনগণকে সচেতন করতে হবে। রেডিও, টেলিভিশন ও প্রচারপত্রের মাধ্যমে সচেতনতা বৃদ্ধি করে প্রতিটি মানুষকে সম্পদের সাশ্রয়ী ব্যবহারে উদ্বুদ্ধ করতে হবে। যথাযথ পরিকল্পনা ও সম্মিলিত প্রচেষ্টার মাধ্যমেই আমাদের প্রাকৃতিক সম্পদ রক্ষা করা সম্ভব।"}]}},{"no":14,"title":"বাংলাদেশের জনসংখ্যা ও জনসম্পদ","q":{"mcq":[{"n":"১","q":"বিনিয়োগ বৃদ্ধির সুফল কোনটি?","a":"ক) কর্মসংস্থান বৃদ্ধি","o":["কর্মসংস্থান বৃদ্ধি","আমদানি বৃদ্ধি","দ্রব্যমূল্য বৃদ্ধি","সঞ্চয় বৃদ্ধি"]},{"n":"২","q":"অধিক বৈদেশিক মুদ্রা অর্জন করতে হলে কী ধরনের জনবল বিদেশে পাঠানো উচিত?","a":"ক) দক্ষ জনবল","o":["দক্ষ জনবল","অল্প দক্ষ জনবল","অদক্ষ জনবল","প্রশিক্ষণবিহীন"]}],"blank":[{"n":"১","q":"দক্ষ মানুষজনই একটি দেশের ______।","a":"জনসম্পদ"},{"n":"২","q":"বিদেশে কর্মরত বাংলাদেশের শ্রমিকদের অধিকাংশই ______ শ্রমিক।","a":"অদক্ষ"},{"n":"৩","q":"একটি শিল্প-কারখানায় যন্ত্রপাতি চালানোর জন্য ______ প্রয়োজন।","a":"দক্ষতা"},{"n":"৪","q":"সাধারণ শিক্ষা গ্রহণ করে অফিস-আদালতে ______ পায়।","a":"চাকরি"}],"truefalse":[{"n":"১","q":"কারিগরি শিক্ষা গ্রহণ দক্ষ জনশক্তি তৈরি করে।","a":"সত্য"},{"n":"২","q":"দক্ষ জনশক্তি রপ্তানি করে প্রচুর বৈদেশিক মুদ্রা অর্জন করা যায়।","a":"সত্য"},{"n":"৩","q":"অর্থনৈতিক উন্নয়নের একমাত্র শর্ত হলো দক্ষ জনশক্তি।","a":"সত্য"}],"match":[{"n":"১","q":"কারিগরি শিক্ষা","a":"নার্স"},{"n":"২","q":"কৃষি শিক্ষা","a":"পশু চিকিৎসক"},{"n":"৩","q":"বৃত্তিমূলক শিক্ষা","a":"ইলেকট্রিশিয়ান"},{"n":"৪","q":"সাধারণ শিক্ষা","a":"শিক্ষক"},{"n":"৫","q":"স্বাস্থ্য শিক্ষা","a":"চিকিৎসক"}],"short":[{"n":"১","q":"জনসংখ্যাকে জনশক্তিতে পরিণত করার তিনটি উপকারিতা লেখ।","a":"জনসংখ্যাকে জনশক্তিতে পরিণত করলে দেশে বেকারত্ব দূর হয় ও নতুন কর্মসংস্থানের সুযোগ সৃষ্টি হয়। এছাড়া দক্ষ জনশক্তি বিদেশে পাঠিয়ে প্রচুর বৈদেশিক মুদ্রা অর্জন করা সম্ভব হয় এবং দেশের সামগ্রিক অর্থনৈতিক উন্নয়ন ও মাথাপিছু আয় বৃদ্ধি পায়।"},{"n":"২","q":"তিনটি বৃত্তিমূলক শিক্ষার নাম লেখ।","a":"আমাদের আলোচনা অনুযায়ী তিনটি জনপ্রিয় বৃত্তিমূলক শিক্ষার নাম হলো:\n• ইলেকট্রিশিয়ান বা ওয়্যারিং শিক্ষা।\n• কম্পিউটার ও মোবাইল মেরামত শিক্ষা।\n• মৎস্য চাষ ও গবাদি পশু পালন শিক্ষা।"}],"essay":[{"n":"১","q":"দেশের উন্নয়ন ত্বরান্বিত করতে কীভাবে জনসংখ্যাকে জনসম্পদে পরিণত করা যায়?","a":"একটি দেশের বিশাল জনসংখ্যা তখনই আশীর্বাদ হয়ে ওঠে, যখন তাদের যথাযথ শিক্ষা ও প্রশিক্ষণের মাধ্যমে দক্ষ করে তোলা হয়। বাংলাদেশের মতো জনবহুল দেশে জনসংখ্যাকে জনসম্পদে রূপান্তরের প্রধান উপায়গুলো নিচে আলোচনা করা হলো:\nপ্রথমত, মানসম্মত ও কর্মমুখী শিক্ষা নিশ্চিত করতে হবে। শুধু সাধারণ শিক্ষায় শিক্ষিত না করে বর্তমান বিশ্বের চাহিদার সাথে মিল রেখে বিজ্ঞান ও প্রযুক্তিভিত্তিক শিক্ষা প্রদান করা প্রয়োজন। দ্বিতীয়ত, কারিগরি ও বৃত্তিমূলক প্রশিক্ষণের ব্যাপক প্রসার ঘটাতে হবে। কম্পিউটার চালনা, মোবাইল মেরামত, ইলেকট্রিক্যাল কাজ বা ড্রাইভিং-এর মতো হাতে-কলমে শেখার সুযোগ বাড়াতে হবে যেন একজন ব্যক্তি সহজেই কর্মসংস্থানের সুযোগ পায়।\nতৃতীয়ত, স্বাস্থ্যসেবা ও পুষ্টির উন্নয়ন অত্যন্ত জরুরি। অসুস্থ জনসংখ্যা দেশের জন্য বোঝা, তাই নাগরিকদের সুস্বাস্থ্য নিশ্চিত করলে তারা দীর্ঘসময় কঠোর পরিশ্রম করতে পারবে। চতুর্থত, নারী শিক্ষার উন্নয়ন ও কর্মসংস্থান নিশ্চিত করতে হবে। দেশের অর্ধেক জনসংখ্যা নারী হওয়ায় তাদের দক্ষ জনশক্তিতে রূপান্তর করলে জাতীয় আয় দ্রুত বৃদ্ধি পাবে। সবশেষে, ক্ষুদ্র ও মাঝারি শিল্পের জন্য ঋণ সহায়তা ও উদ্যোক্তা তৈরির সুযোগ দিতে হবে। এর ফলে মানুষ নিজের দক্ষতা কাজে লাগিয়ে স্বাবলম্বী হতে পারবে এবং অন্যের জন্যও কর্মসংস্থান তৈরি করবে। মূলত দক্ষ জনশক্তিই বিদেশি বিনিয়োগ আকর্ষণ করে এবং রেমিট্যান্স প্রবাহ বাড়িয়ে দেশের অর্থনৈতিক উন্নয়নকে ত্বরান্বিত করে।"},{"n":"২","q":"বাংলাদেশে বিভিন্ন পেশার জনসম্পদের বিবরণ দাও।","a":"বাংলাদেশের বিশাল জনগোষ্ঠী বিভিন্ন পেশায় নিয়োজিত থেকে দেশের অর্থনীতিতে গুরুত্বপূর্ণ অবদান রাখছে। পেশার ধরন অনুযায়ী আমাদের জনসম্পদকে কয়েকটি প্রধান ভাগে ভাগ করা যায়:\n• কৃষি ও মৎস্য খাতের জনসম্পদ: বাংলাদেশের অধিকাংশ মানুষ কৃষির ওপর নির্ভরশীল। আধুনিক প্রযুক্তি ও উচ্চফলনশীল বীজ ব্যবহারে দক্ষ কৃষকরা খাদ্যে স্বয়ংসম্পূর্ণতা আনছেন। এছাড়া মৎস্য চাষ ও পশুপালনে প্রশিক্ষিত জনবল দেশের পুষ্টি চাহিদা মিটিয়ে বিদেশে মাছ ও মাংস রপ্তানি করছে।\n• শিল্প ও কারিগরি পেশাজীবী: আমাদের দেশের একটি বড় অংশ পোশাক শিল্প (Garments Industry) ও বিভিন্ন কলকারখানায় শ্রমিক হিসেবে কাজ করে। এছাড়া ইলেকট্রিশিয়ান, ওয়েল্ডার, দর্জি এবং ইঞ্জিনিয়াররা দেশের অবকাঠামো উন্নয়নে ও শিল্প উৎপাদনে প্রধান ভূমিকা পালন করছেন।\n• সেবা খাতের পেশাজীবী: এই খাতে শিক্ষক, চিকিৎসক, নার্স এবং ব্যাংক কর্মকর্তারা কাজ করেন। শিক্ষকরা দক্ষ নাগরিক গড়ে তোলেন, আর চিকিৎসকরা জনগণকে সুস্থ ও কর্মক্ষম রেখে জাতীয় উৎপাদনে সহায়তা করেন।\n• তথ্যপ্রযুক্তি ও ফ্রিল্যান্সিং: বর্তমান প্রজন্মের একটি বড় অংশ আইটি (IT) খাতে দক্ষ হয়ে উঠছে। সফটওয়্যার ইঞ্জিনিয়ার, গ্রাফিক ডিজাইনার এবং ডিজিটাল মার্কেটিং বিশেষজ্ঞরা ঘরে বসেই বৈদেশিক মুদ্রা আয় করছেন, যা দেশের অর্থনীতিকে আধুনিক ও গতিশীল করছে।\nউপসংহারে বলা যায়, বিভিন্ন পেশার এই দক্ষ জনবলই বাংলাদেশের অর্থনীতির মূল ভিত্তি। তাদের সঠিক মূল্যায়ন ও নিয়মিত প্রশিক্ষণ দেশের ভবিষ্যৎ আরও উজ্জ্বল করতে পারে।"}]}},{"no":15,"title":"ব্যক্তিগত বাজেট ও ব্যাংক","q":{"mcq":[{"n":"১","q":"ভবিষ্যতের প্রয়োজনে কী করতে হয়?","a":"খ) টাকাপয়সা সঞ্চয়","o":["আসবাবপত্র ক্রয়","টাকাপয়সা সঞ্চয়","আয় উপার্জন","অর্থ ব্যয়"]},{"n":"২","q":"একজন ব্যক্তি তার আয়ের অর্থ ভবিষ্যতে কীভাবে খরচ করবে- এই পরিকল্পনাকে কী বলে?","a":"ঘ) বাজেট","o":["সঞ্চয়","বিনিয়োগ","মুনাফা","বাজেট"]},{"n":"৩","q":"ব্যাংকে ব্যক্তি ও প্রতিষ্ঠানের সঞ্চিত অর্থে কী গড়ে ওঠে?","a":"খ) মুনাফা","o":["মূলধন","মুনাফা","বিনিয়োগ","ক্ষুদ্র ঋণ"]}],"blank":[{"n":"১","q":"একজন ব্যক্তির একটি নির্দিষ্ট সময়ের আয় ও ব্যয়ের ______ ব্যক্তিগত বাজেট।","a":"পরিকল্পনা"},{"n":"২","q":"আয় থেকে ব্যয় করার পর যে উদ্বৃত্ত থাকে সেটা ______।","a":"সঞ্চয়"},{"n":"৩","q":"ব্যাংক এক ধরনের ______ প্রতিষ্ঠান।","a":"আর্থিক"},{"n":"৪","q":"ব্যাংকে টাকাপয়সা সঞ্চয়ের বিনিময়ে ______ পাওয়া যায়।","a":"মুনাফা"}],"match":[{"n":"১","q":"ব্যাংকে টাকা জমা দেওয়ার জন্য","a":"রসিদ ব্যবহার করা হয়"},{"n":"২","q":"ব্যাংক থেকে টাকা উঠানোর জন্য","a":"চেক ব্যবহার করতে হয়"},{"n":"৩","q":"মুনাফা অর্জন করতে হলে ব্যাংকে","a":"টাকা জমা রাখতে হয়"}],"short":[{"n":"১","q":"ব্যাংকের প্রধান কাজ কী কী?","a":"ব্যাংকের প্রধান কাজ হলো গ্রাহকদের অলস টাকা নিরাপদে আমানত হিসেবে জমা রাখা এবং সংগৃহীত সেই টাকা থেকে ব্যবসায়ী বা উদ্যোক্তাদের ঋণ প্রদান করা। এছাড়া ব্যাংক গ্রাহকদের লেনদেনে নিরাপত্তা নিশ্চিত করে এবং জমানো টাকার ওপর মুনাফা প্রদান করে।"},{"n":"২","q":"ব্যক্তিগত বাজেট কী?","a":"ব্যক্তিগত বাজেট হলো একজন ব্যক্তির একটি নির্দিষ্ট সময়ের (যেমন: এক মাস) সম্ভাব্য আয় ও ব্যয়ের লিখিত পূর্ব পরিকল্পনা। এটি মূলত আয় বুঝে ব্যয়ের হিসাব ঠিক রাখতে এবং অপ্রয়োজনীয় খরচ কমিয়ে সঞ্চয় করতে সাহায্য করে।"},{"n":"৩","q":"সঞ্চয়ী হওয়ার সুবিধা কী?","a":"সঞ্চয়ী হওয়ার প্রধান সুবিধা হলো এটি ভবিষ্যতের যেকোনো আপদকালীন বা জরুরি প্রয়োজনে (যেমন: অসুস্থতা বা হঠাৎ কোনো খরচ) আর্থিক নিরাপত্তা দেয়। এছাড়া নিয়মিত সঞ্চয়ের ফলে বড় অংকের পুঁজি গঠিত হয়, যা দিয়ে ভবিষ্যতে বড় কোনো শখ পূরণ বা বিনিয়োগ করা সম্ভব হয়।"}],"essay":[{"n":"১","q":"তুমি বাবার কাছ থেকে ৮০ টাকা, মায়ের কাছ থেকে ৬০ টাকা ও বড়ো ভাইয়ের কাছ থেকে ৩০ টাকা পেয়েছ। স্কুলের টিফিন, খাতা, কলম, পেনসিল কেনায় ব্যয় দেখিয়ে একটি ব্যক্তিগত বাজেট তৈরি করো।","a":"আয়ের বিবরণী/খাত | আয় (টাকা) | খরচের বিবরণী/খাত | সম্ভাব্য খরচ (টাকা) | মন্তব্য\nবাবার কাছ থেকে প্রাপ্তি | ৮০ | খাতা কেনা | ৫০ | প্রয়োজনীয় শিক্ষা উপকরণ\nমায়ের কাছ থেকে প্রাপ্তি | ৬০ | কলম ও পেনসিল কেনা | ৩০ | প্রয়োজনীয় শিক্ষা উপকরণ\nবড় ভাইয়ের কাছ থেকে প্রাপ্তি | ৩০ | স্কুলের টিফিন | ৬০ | হালকা নাস্তা\n| | সঞ্চয় | ৩০ | মাটির ব্যাংকে জমা\nমোট আয় = | ১৭০ টাকা | মোট খরচ = | ১৭০ টাকা | আয় ও ব্যয় সমান\nবাজেটটির সংক্ষিপ্ত বর্ণনা:\n১. মোট আয়: বাবা, মা ও বড় ভাইয়ের কাছ থেকে পাওয়া মোট আয়ের পরিমাণ ১৭০ টাকা।\n২. ব্যয় ও সঞ্চয়: শিক্ষা উপকরণ (খাতা, কলম, পেনসিল) এবং টিফিন বাবদ মোট ১৪০ টাকা খরচ ধরা হয়েছে।\n৩. উদ্বৃত্ত: আয়ের বাকি ৩০ টাকা সরাসরি খরচ না করে ভবিষ্যতের জন্য সঞ্চয় রাখা হয়েছে, যা একটি আদর্শ বাজেটের বৈশিষ্ট্য।"}]}},{"no":16,"title":"জরুরি পরিস্থিতি","q":{"blank":[{"n":"১","q":"জলোচ্ছ্বাস একটি ______ দুর্যোগ।","a":"প্রাকৃতিক"},{"n":"২","q":"উপকূলীয় এলাকায় জলোচ্ছ্বাসে ______ হয়।","a":"ক্ষয়ক্ষতি"},{"n":"৩","q":"বাংলাদেশে বজ্রপাতজনিত মৃত্যুর সংখ্যা ক্রমশ ______।","a":"বাড়ছে"},{"n":"৪","q":"দুর্যোগকালে স্বেচ্ছাসেবক দল বিভিন্নভাবে ______ করে।","a":"সহায়তা"}],"short":[{"n":"১","q":"জলোচ্ছ্বাসের পূর্বে তিনটি প্রস্তুতিমূলক কাজ লেখ।","a":"জলোচ্ছ্বাসের পূর্বে গুরুত্বপূর্ণ দলিল ও শুকনো খাবার পলিথিনে মুড়িয়ে সাথে রাখা, গবাদি পশুকে উঁচু স্থানে সরিয়ে নেওয়া এবং বাড়ির টিউবওয়েলের মুখ পলিথিন দিয়ে ভালোভাবে আটকে রাখা প্রয়োজন।"},{"n":"২","q":"বজ্রপাতের ফলে কী ক্ষতি হয়?","a":"বজ্রপাতের ফলে মানুষ ও পশুপাখির প্রাণহানি ঘটে, গাছপালা পুড়ে যায় এবং বাড়ির বৈদ্যুতিক সরঞ্জাম বা যন্ত্রপাতি নষ্ট হয়ে বড় ধরনের আর্থিক ক্ষতি হতে পারে।"},{"n":"৩","q":"জরুরি সেবা পেতে তিনটি সংস্থার নাম ও যোগাযোগের নম্বর লেখ।","a":"জরুরি সেবা পেতে আমরা ৯৯৯ (জরুরি সেবা), ১০৯০ (দুর্যোগের আগাম বার্তা) এবং ৩৩৩ (সরকারি তথ্য ও সেবা) নম্বরগুলোতে যোগাযোগ করতে পারি।"}],"essay":[{"n":"১","q":"বজ্রপাতের সময় তুমি কী কী করবে?","a":"বজ্রপাত একটি প্রাণঘাতী দুর্যোগ, যা থেকে বাঁচতে সচেতনতাই একমাত্র পথ। বজ্রপাতের সময় আমি নিজেকে ও অন্যদের নিরাপদ রাখতে নিচের পদক্ষেপগুলো গ্রহণ করব:\n• পাকা দালানের নিচে আশ্রয়: বজ্রপাত শুরু হওয়ার সাথে সাথে আমি দ্রুত কোনো পাকা দালানের নিচে আশ্রয় নেব। যদি এমন কোনো ভবন না থাকে, তবে টিনের চালের ঘর এড়িয়ে চলার চেষ্টা করব এবং কোনো উঁচু গাছের নিচে দাঁড়াব না। কারণ বজ্রপাত সাধারণত উঁচু স্থানে বা গাছের ওপর বেশি আঘাত হানে।\n• ইলেকট্রনিক যন্ত্র ব্যবহার বন্ধ করা: ঘরের ভেতরে থাকাকালীন আমি মোবাইল ফোন, ল্যাপটপ বা টেলিভিশন ব্যবহার করা থেকে বিরত থাকব। সব বৈদ্যুতিক যন্ত্রের প্লাগ সকেট থেকে খুলে রাখব এবং ল্যান্ডফোন ব্যবহার করব না।\n• উন্মুক্ত স্থান ও জলাশয় ত্যাগ: যদি আমি খোলা মাঠে থাকি, তবে দ্রুত নিরাপদ আশ্রয়ের দিকে ছুটব। কাছাকাছি কোনো আশ্রয় না থাকলে উবু হয়ে বসে পড়ব এবং মাথা দুই হাঁটুর মাঝখানে রাখব, তবে মাটিতে শুয়ে পড়ব না। এছাড়া পুকুর বা নদী থেকে দূরে থাকব, কারণ পানি বিদ্যুতের সুপরিবাহী।\n• ধাতব বস্তু থেকে দূরত্ব: কোনো ধরনের লোহার খুঁটি, গ্রিল বা ধাতব পাইপ স্পর্শ করব না। নৌকায় থাকলে নিচু হয়ে বসে পড়ার চেষ্টা করব।"},{"n":"২","q":"জলোচ্ছ্বাসপ্রবণ এলাকায় দুর্যোগ পূর্ববর্তী এবং পরবর্তী সময়ে সরকারি ও বেসরকারি সংস্থার কার্যক্রমগুলো বর্ণনা করো।","a":"জলোচ্ছ্বাসপ্রবণ এলাকায় মানুষের জীবন ও সম্পদ রক্ষায় সরকারি ও বেসরকারি (NGO) সংস্থাগুলো সমন্বিতভাবে কাজ করে। তাদের কার্যক্রম নিচে বর্ণনা করা হলো:\n• দুর্যোগ পূর্ববর্তী কার্যক্রম: দুর্যোগ আঘাত হানার আগেই সংস্থাগুলো প্রস্তুতির ওপর জোর দেয়। আবহাওয়া অধিদপ্তরের মাধ্যমে ঝড়ের গতিপথ পর্যবেক্ষণ করে উপকূলীয় এলাকায় মাইকিংয়ের মাধ্যমে নিয়মিত সতর্কবার্তা পৌঁছে দেয়। সরকারিভাবে ইউনিয়ন দুর্যোগ ব্যবস্থাপনা কমিটি গঠন করা হয়, যারা স্থানীয় স্বেচ্ছাসেবকদের প্রশিক্ষণ দেয়। এছাড়া মানুষকে নিরাপদ আশ্রয়কেন্দ্রে সরিয়ে নেওয়া, গবাদি পশুর জন্য নিরাপদ উঁচু জায়গা তৈরি করা এবং শুকনো খাবার ও বিশুদ্ধ পানি মজুত রাখার কাজে এই সংস্থাগুলো নেতৃত্ব দেয়।\n• দুর্যোগ পরবর্তী কার্যক্রম: জলোচ্ছ্বাস থেমে যাওয়ার পর উদ্ধার অভিযান শুরু করা হয়। দুর্যোগে আটকে পড়া মানুষকে উদ্ধার করে হাসপাতালে পাঠানো বা প্রাথমিক চিকিৎসা দেওয়ার কাজটি স্বেচ্ছাসেবক ও সরকারি মেডিকেল টিম করে থাকে। ক্ষতিগ্রস্তদের মাঝে শুকনো খাবার, পানি বিশুদ্ধকরণ ট্যাবলেট এবং জরুরি ত্রাণ সামগ্রী বিতরণ করা হয়। বেসরকারি সংস্থাগুলো ক্ষতিগ্রস্ত ঘরবাড়ি, রাস্তাঘাট ও বাঁধ মেরামতে আর্থিক ও কারিগরি সহায়তা দেয়। এছাড়া লবণাক্ত পানিতে তলিয়ে যাওয়া ফসলি জমি বা টিউবওয়েল সংস্কার করে পুনরায় চাষাবাদ ও বিশুদ্ধ পানির ব্যবস্থা নিশ্চিত করা হয়।\nসংক্ষেপে, এই সংস্থাগুলোর সময়োচিত পদক্ষেপ ও সঠিক ব্যবস্থাপনার কারণেই বর্তমানে আমাদের দেশে জলোচ্ছ্বাসের মতো ভয়াবহ দুর্যোগেও প্রাণহানির সংখ্যা অনেক কমে এসেছে।"}]}}]};